/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8 */ ;
/*!50003 SET character_set_results = utf8 */ ;
/*!50003 SET collation_connection  = utf8_general_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'NO_AUTO_CREATE_USER,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
/*!50003 CREATE*/ /*!50017 */ /*!50003 TRIGGER `yichong_reset_approveinfo_approvelog_insert` BEFORE INSERT ON `ld_approvelog` FOR EACH ROW BEGIN 

	IF @disable_triggers IS NULL THEN
		IF NEW.approveid IN (72,73) AND NEW.stepid=-1 THEN
			SET @yc_approve_crmid=NEW.crmid;
			IF EXISTS (SELECT 1 FROM ld_crmentity WHERE crmid=@yc_approve_crmid AND setype IN ('Quotes','CustomForm11')) THEN
				IF IFNULL((SELECT price_info FROM ld_quotes WHERE quoteid=@yc_approve_crmid),'')='无需审批' OR IFNULL((SELECT qty_info FROM ld_customform11 WHERE customform11id=@yc_approve_crmid),'')='无需审批' THEN
					SET NEW.description='无需审批';
					INSERT INTO 00_noneapprove(logid) SELECT NEW.id;
				END IF;
			END IF;
		END IF;
	END IF;

END */;;
DELIMITER ;
