/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8 */ ;
/*!50003 SET character_set_results = utf8 */ ;
/*!50003 SET collation_connection  = utf8_general_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'NO_AUTO_CREATE_USER,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
/*!50003 CREATE*/ /*!50017 */ /*!50003 TRIGGER `yc_resetinfo_customform11_edd` BEFORE UPDATE ON `ld_customform11` FOR EACH ROW BEGIN 

	IF @disable_triggers IS NULL THEN
		SET NEW.kehu_name=(SELECT accountname FROM ld_account WHERE accountid=NEW.accountid);

		SET NEW.owner_role=(
			SELECT
				a.userlevel
			FROM ld_users a
			WHERE a.id=NEW.smownerid
		);
	
		SET @ycqty_customform11id=NEW.customform11id;

		
		
		
		SET NEW.qty_info=(
			SELECT
				CASE
					WHEN MAX(price_info)=0 THEN '无需审批'
					WHEN MAX(price_info)=11 THEN '总经理审批'
					WHEN MAX(price_info)=21 THEN '总监审批'
					WHEN MAX(price_info)=22 THEN '总监审批+总经理审批'
					WHEN MAX(price_info)=31 THEN '经理审批'
					WHEN MAX(price_info)=32 THEN '经理审批+总监审批'
					WHEN MAX(price_info)=33 THEN '经理审批+总监审批+总经理审批'
					WHEN MAX(price_info)=34 THEN '经理审批+总监审批+总经理审批'
				END AS approve_info
			FROM (
				SELECT 
					CASE
						
						WHEN IFNULL(u.userlevel,'') NOT IN ('部门经理','总监','总经理','副总经理') AND a.quantity<=IFNULL(c.cf_3935,0) THEN 0

						
						WHEN IFNULL(u.userlevel,'') NOT IN ('部门经理','总监','总经理','副总经理') AND a.quantity>IFNULL(c.cf_3935,0) AND a.quantity<=IFNULL(c.cf_3936,0) THEN 31

						
						WHEN IFNULL(u.userlevel,'') NOT IN ('部门经理','总监','总经理','副总经理') AND a.quantity>IFNULL(c.cf_3936,0) AND a.quantity<=IFNULL(c.cf_4015,0) THEN 32

						
						WHEN IFNULL(u.userlevel,'') NOT IN ('部门经理','总监','总经理','副总经理') AND a.quantity>IFNULL(c.cf_4015,0) THEN 33

						
						WHEN IFNULL(u.userlevel,'') IN ('部门经理') AND a.quantity<=IFNULL(c.cf_3936,0) THEN 0

						
						WHEN IFNULL(u.userlevel,'') IN ('部门经理') AND a.quantity>IFNULL(c.cf_3936,0) AND a.quantity<=IFNULL(c.cf_4015,0) THEN 21

						
						WHEN IFNULL(u.userlevel,'') IN ('部门经理') AND a.quantity>IFNULL(c.cf_4015,0) THEN 22

						
						WHEN IFNULL(u.userlevel,'') IN ('总监') AND a.quantity<=IFNULL(c.cf_4015,0) THEN 0

						
						WHEN IFNULL(u.userlevel,'') IN ('总监') AND a.quantity>IFNULL(c.cf_4015,0) THEN 11

						
						WHEN IFNULL(u.userlevel,'') IN ('总经理','副总经理') THEN 0

						
						ELSE 34
					END AS price_info
				FROM ld_customform11detail a 
				LEFT JOIN ld_customform11detailscf b ON a.lineitem_id=b.lineitem_id 
				LEFT JOIN ld_productcf c ON c.productid=a.productid 
				LEFT JOIN ld_customform11 q ON a.id=q.customform11id
				LEFT JOIN ld_users u ON u.id=q.smownerid
				WHERE a.id=@ycqty_customform11id
			) a
		);
		
		IF NEW.approvestatus='审批中' AND NEW.qty_info='无需审批' AND IFNULL((SELECT approveid FROM ld_approvelog WHERE crmid=@ycqty_customform11id ORDER BY id DESC LIMIT 1),0)=73 THEN
			SET NEW.approvestatus='已批准';
			SET NEW.currentapprover=NULL;
			SET NEW.approveby=NEW.approvesubmitter;
		END IF;
	END IF;

END */;;
DELIMITER ;
