DELIMITER ;;
/*!50003 CREATE*/ /*!50017 */ /*!50003 TRIGGER `yichong_reset_customform21info_form21update` BEFORE UPDATE ON `ld_customform21` FOR EACH ROW BEGIN 

	IF @disable_triggers IS NULL THEN
		IF NEW.quote_id>0 THEN
			SET @yc_form21_quoteid=NEW.quote_id;
			SELECT 
				NULL,
				NULL,
				NULL,
				NULL,
				NULL,
				NULL,
				NULL,
				NULL,
				NULL	
			INTO 
				@quote_price_jy,
				@quote_price_dl,
				@quote_price_dg,
				@quote_price_pp,
				@quote_price_cb,
				@quote_lirun_dl,
				@quote_lirun_dg,
				@quote_lirun,
				@baojia_rate;


			SELECT 
				ROUND(SUM(a.taxprice*a.quantity),2) AS jy,
				ROUND(SUM(b.sf8363*a.quantity),2) AS dl,
				ROUND(SUM(b.sf7411*a.quantity),2) AS dg,
				ROUND(SUM(b.sf7547*a.quantity),2) AS pp,
				ROUND(SUM(b.sf9315*a.quantity),2) AS cb,
				CONCAT(ROUND((ROUND(SUM(b.sf7411*a.quantity),2)-ROUND(SUM(b.sf8363*a.quantity),2))*100/ROUND(SUM(b.sf7411*a.quantity),2),2),'%'),
				CONCAT(ROUND((ROUND(SUM(b.sf7547*a.quantity),2)-ROUND(SUM(b.sf7411*a.quantity),2))*100/ROUND(SUM(b.sf7547*a.quantity),2),2),'%'),
				CONCAT(ROUND((ROUND(SUM(a.taxprice*a.quantity),2)-ROUND(SUM(b.sf9315*a.quantity),2))*100/ROUND(SUM(a.taxprice*a.quantity),2),2),'%'),
				ROUND(b.sf7275,6) AS rate
			INTO 
				@quote_price_jy,
				@quote_price_dl,
				@quote_price_dg,
				@quote_price_pp,
				@quote_price_cb,
				@quote_lirun_dl,
				@quote_lirun_dg,
				@quote_lirun,
				@baojia_rate
			FROM ld_quotesdetail a 
			LEFT JOIN ld_quotesdetailscf b On b.lineitem_id=a.lineitem_id
			WHERE a.id=@yc_form21_quoteid;

			SET NEW.quote_price_jy=@quote_price_jy;
			SET NEW.quote_price_dl=@quote_price_dl;
			SET NEW.quote_price_dg=@quote_price_dg;
			SET NEW.quote_price_pp=@quote_price_pp;
			SET NEW.quote_price_cb=@quote_price_cb;
			SET NEW.quote_lirun_dl=IFNULL(@quote_lirun_dl,0);
			SET NEW.quote_lirun_dg=IFNULL(@quote_lirun_dg,0);
			SET NEW.quote_lirun=IFNULL(@quote_lirun,0);
			SET NEW.baojia_rate=@baojia_rate;
		ELSE 
			SET NEW.quote_price_jy=NULL;
			SET NEW.quote_price_dl=NULL;
			SET NEW.quote_price_dg=NULL;
			SET NEW.quote_price_pp=NULL;
			SET NEW.quote_price_cb=NULL;
			SET NEW.quote_lirun_dl=NULL;
			SET NEW.quote_lirun_dg=NULL;
			SET NEW.quote_lirun=NULL;
			SET NEW.baojia_rate=NULL;
			SET NEW.baojia_bizhong=NULL;
		END IF;
	END IF;

END */;;
DELIMITER ;
