'Potentials','2021-09-03 11:58:29',NULL,0,NULL,0,'','desc',1,'',0,'0','no','no','','yes','Bottom',58,NULL,NULL,NULL,NULL,NULL),(25,'员工待转化线索','统计每个员工名下未转化成客户的线索数量','chart',1,24,'Leads','2022-07-21 15:41:34',NULL,0,NULL,0,'','desc',1,'',0,'no','no','no','','yes','Bottom',58,NULL,NULL,NULL,NULL,NULL),(26,'本季度预计成交重点商机TOP10','根据预计成交日期，按照非成交或失败状态的商机按预计合同金额大小排名','chart',1,25,'Potentials','2022-07-26 14:17:42',NULL,0,NULL,10,'','desc',1,'',0,'no','no','no','','yes','Bottom',58,NULL,NULL,'[null,{\"groupid\":\"1\",\"columnname\":\"ld_potential:sales_stage:sales_stage:Potentials_销售阶段:V\",\"comparator\":\"k\",\"value\":\"成功\",\"columncondition\":\"\"},{\"groupid\":\"1\",\"columnname\":\"ld_potential:closingdate:closingdate:Potentials_预计成交日期  :D\",\"comparator\":\"thisfq\",\"value\":\"2022-07-01\",\"columncondition\":\"and\"},{\"groupid\":\"1\",\"columnname\":\"ld_potential:sales_stage:sales_stage:Potentials_销售阶段:V\",\"comparator\":\"k\",\"value\":\"失败\",\"columncondition\":\"and\"}]',NULL,NULL),(305,'产品签约数量同比','','sqlchart',NULL,0,NULL,'2023-11-22 16:31:40','2023-11-28 19:17:21',0,1,NULL,NULL,NULL,1,NULL,0,'yes','no','no',NULL,'yes','Bottom',73,'SELECT\n	p_num.where_time,\n	p_num.group_time,\n	(\n		CASE\n		WHEN \'{timetype}\' = \'本年和去年-按季度\' THEN\n			CONCAT(\n				\'第\',\n				p_num.group_time,\n				\'季度\'\n			)\n		ELSE\n			CONCAT(p_num.group_time, \'月\')\n		END\n	) AS dispaly_group_time,\n	sum(p_num.pre_num) AS pre_num,\n	sum(p_num.now_num) AS now_num\nFROM\n	(\n		(\n			SELECT\n				timetype_table.where_time AS where_time,\n				timetype_table.group_time AS group_time,\n				pre_salesorder.salesorderid AS pre_id,\n				pre_salesorder.quantity AS pre_num,\n				now_salesorder.salesorderid AS now_id,\n				now_salesorder.quantity AS now_num\n			FROM\n				(\n					SELECT\n						(\n							CASE\n							WHEN \'{timetype}\' = \'本年和去年-按月\' THEN\n								YEAR (NOW())\n							WHEN \'{timetype}\' = \'本年和去年-按季度\' THEN\n								YEAR (NOW())\n							WHEN \'{timetype}\' = \'本季度和上季度-按月\' THEN\n								QUARTER (NOW())\n							ELSE\n								YEAR (NOW())\n							END\n						) AS where_time,\n						(\n							CASE\n							WHEN \'{timetype}\' = \'本年和去年-按月\' THEN\n								MONTH (date)\n							WHEN \'{timetype}\' = \'本年和去年-按季度\' THEN\n								QUARTER (date)\n							WHEN \'{timetype}\' = \'本季度和上季度-按月\' THEN\n								MONTH (date)\n							ELSE\n								MONTH (date)\n							END\n						) AS group_time\n					FROM\n						tmp_date a\n					WHERE\n						date LIKE \'%2023%\'\n					GROUP BY\n						group_time\n				) timetype_table\n			LEFT JOIN (\n				SELECT\n					ld_salesorder.salesorderid,\n					(\n						CASE\n						WHEN \'{timetype}\' = \'本年和去年-按月\' THEN\n							YEAR (ld_salesorder.signed_data)\n						WHEN \'{timetype}\' = \'本年和去年-按季度\' THEN\n							YEAR (ld_salesorder.signed_data)\n						WHEN \'{timetype}\' = \'本季度和上季度-按月\' THEN\n							QUARTER (ld_salesorder.signed_data)\n						ELSE\n							YEAR (ld_salesorder.signed_data)\n						END\n					) AS where_time,\n					(\n						CASE\n						WHEN \'{timetype}\' = \'本年和去年-按月\' THEN\n							MONTH (ld_salesorder.signed_data)\n						WHEN \'{timetype}\' = \'本年和去年-按季度\' THEN\n							QUARTER (ld_salesorder.signed_data)\n						WHEN \'{timetype}\' = \'本季度和上季度-按月\' THEN\n							MONTH (ld_salesorder.signed_data)\n						ELSE\n							MONTH (ld_salesorder.signed_data)\n						END\n					) AS group_time,\n					sum(now_s_detail.quantity) AS quantity\n				FROM\n					ld_salesorder\n				LEFT JOIN ld_salesorderdetail now_s_detail ON now_s_detail.id = ld_salesorder.salesorderid\n				LEFT JOIN ld_products ON ld_products.productid = now_s_detail.productid\n				WHERE\n					(\n						ld_products.productname = \'{productname}\'\n						OR \'{productname}\' = \'\'\n					)\n				AND (\n					\'{productcategory}\' = \'\'\n					OR FIND_IN_SET(\n						ld_products.productcategory,\n						\'{productcategory}\'\n					)\n				)\n				AND FIND_IN_SET(\n					ld_salesorder.approvestatus,\n					\'{approvestatus}\'\n				)\n				AND FIND_IN_SET(\n					ld_salesorder.smownerid,\n					\'{userscope}\'\n				)\n				AND (\n					ld_salesorder.signed_data BETWEEN \'{starttime}\'\n					AND \'{endtime}\'\n				)\n				GROUP BY\n					where_time,\n					group_time\n			) now_salesorder ON now_salesorder.where_time = timetype_table.where_time\n			AND now_salesorder.group_time = timetype_table.group_time\n			LEFT JOIN (\n				SELECT\n					ld_salesorder.salesorderid,\n					(\n						CASE\n						WHEN \'{timetype}\' = \'本年和去年-按月\' THEN\n							YEAR (\n								DATE_ADD(\n									ld_salesorder.signed_data,\n									INTERVAL 1 YEAR\n								)\n							)\n						WHEN \'{timetype}\' = \'本年和去年-按季度\' THEN\n							YEAR (\n								DATE_ADD(\n									ld_salesorder.signed_data,\n									INTERVAL 1 YEAR\n								)\n							)\n						WHEN \'{timetype}\' = \'本季度和上季度-按月\' THEN\n							QUARTER (\n								DATE_ADD(\n									ld_salesorder.signed_data,\n									INTERVAL 1 QUARTER\n								)\n							)\n						ELSE\n							YEAR (\n								DATE_ADD(\n									ld_salesorder.signed_data,\n									INTERVAL 1 YEAR\n								)\n							)\n						END\n					) AS where_time,\n					(\n						CASE\n						WHEN \'{timetype}\' = \'本年和去年-按月\' THEN\n							MONTH (ld_salesorder.signed_data)\n						WHEN \'{timetype}\' = \'本年和去年-按季度\' THEN\n							QUARTER (signed_data)\n						WHEN \'{timetype}\' = \'本季度和上季度-按月\' THEN\n							MONTH (ld_salesorder.signed_data)\n						ELSE\n							MONTH (ld_salesorder.signed_data)\n						END\n					) AS group_time,\n					sum(pre_s_detail.quantity) AS quantity\n				FROM\n					ld_salesorder\n				LEFT JOIN ld_salesorderdetail pre_s_detail ON pre_s_detail.id = ld_salesorder.salesorderid\n				LEFT JOIN ld_products ON ld_products.productid = pre_s_detail.productid\n				WHERE\n					(\n						ld_products.productname = \'{productname}\'\n						OR \'{productname}\' = \'\'\n					)\n				AND (\n					\'{productcategory}\' = \'\'\n					OR FIND_IN_SET(\n						ld_products.productcategory,\n						\'{productcategory}\'\n					)\n				)\n				AND FIND_IN_SET(\n					ld_salesorder.approvestatus,\n					\'{approvestatus}\'\n				)\n				AND FIND_IN_SET(\n					ld_salesorder.smownerid,\n					\'{userscope}\'\n				)\n				GROUP BY\n					where_time,\n					group_time\n			) pre_salesorder ON pre_salesorder.where_time = timetype_table.where_time\n			AND pre_salesorder.group_time = timetype_table.group_time\n			GROUP BY\n				timetype_table.group_time\n		)\n		UNION ALL\n			(\n				SELECT\n					timetype_table.where_time AS where_time,\n					timetype_table.group_time AS group_time,\n					pre_servicecontracts.servicecontractsid AS pre_id,\n					pre_servicecontracts.quantity AS pre_num,\n					now_servicecontracts.servicecontractsid AS now_id,\n					now_servicecontracts.quantity AS now_num\n				FROM\n					(\n						SELECT\n							(\n								CASE\n								WHEN \'{timetype}\' = \'本年和去年-按月\' THEN\n									YEAR (NOW())\n								WHEN \'{timetype}\' = \'本年和去年-按季度\' THEN\n									YEAR (NOW())\n								WHEN \'{timetype}\' = \'本季度和上季度-按月\' THEN\n									QUARTER (NOW())\n								ELSE\n									YEAR (NOW())\n								END\n							) AS where_time,\n							(\n								CASE\n								WHEN \'{timetype}\' = \'本年和去年-按月\' THEN\n									MONTH (date)\n								WHEN \'{timetype}\' = \'本年和去年-按季度\' THEN\n									QUARTER (date)\n								WHEN \'{timetype}\' = \'本季度和上季度-按月\' THEN\n									MONTH (date)\n								ELSE\n									MONTH (date)\n								END\n							) AS group_time\n						FROM\n							tmp_date a\n						WHERE\n							date LIKE \'%2023%\'\n						GROUP BY\n							group_time\n					) timetype_table\n				LEFT JOIN (\n					SELECT\n						ld_servicecontracts.servicecontractsid,\n						(\n							CASE\n							WHEN \'{timetype}\' = \'本年和去年-按月\' THEN\n								YEAR (due_date)\n							WHEN \'{timetype}\' = \'本年和去年-按季度\' THEN\n								YEAR (due_date)\n							WHEN \'{timetype}\' = \'本季度和上季度-按月\' THEN\n								QUARTER (due_date)\n							ELSE\n								YEAR (due_date)\n							END\n						) AS where_time,\n						(\n							CASE\n							WHEN \'{timetype}\' = \'本年和去年-按月\' THEN\n								MONTH (due_date)\n							WHEN \'{timetype}\' = \'本年和去年-按季度\' THEN\n								QUARTER (due_date)\n							WHEN \'{timetype}\' = \'本季度和上季度-按月\' THEN\n								MONTH (due_date)\n							ELSE\n								MONTH (due_date)\n							END\n						) AS group_time,\n						sum(now_sv_detail.quantity) AS quantity\n					FROM\n						ld_servicecontracts\n					LEFT JOIN ld_servicecontractsdetail now_sv_detail ON now_sv_detail.id = ld_servicecontracts.servicecontractsid\n					LEFT JOIN ld_products ON ld_products.productid = now_sv_detail.productid\n					WHERE\n						(\n							ld_products.productname = \'{productname}\'\n							OR \'{productname}\' = \'\'\n						)\n					AND (\n						\'{productcategory}\' = \'\'\n						OR FIND_IN_SET(\n							ld_products.productcategory,\n							\'{productcategory}\'\n						)\n					)\n					AND FIND_IN_SET(\n						ld_servicecontracts.approvestatus,\n						\'{approvestatus}\'\n					)\n					AND FIND_IN_SET(\n						ld_servicecontracts.smownerid,\n						\'{userscope}\'\n					)\n					AND (\n						ld_servicecontracts.due_date BETWEEN \'{starttime}\'\n						AND \'{endtime}\'\n					)\n					GROUP BY\n						where_time,\n						group_time\n				) now_servicecontracts ON now_servicecontracts.where_time = timetype_table.where_time\n				AND now_servicecontracts.group_time = timetype_table.group_time\n				LEFT JOIN (\n					SELECT\n						ld_servicecontracts.servicecontractsid,\n						(\n							CASE\n							WHEN \'{timetype}\' = \'本年和去年-按月\' THEN\n								YEAR (\n									DATE_ADD(\n										ld_servicecontracts.due_date,\n										INTERVAL 1 YEAR\n									)\n								)\n							WHEN \'{timetype}\' = \'本年和去年-按季度\' THEN\n								YEAR (\n									DATE_ADD(\n										ld_servicecontracts.due_date,\n										INTERVAL 1 YEAR\n									)\n								)\n							WHEN \'{timetype}\' = \'本季度和上季度-按月\' THEN\n								QUARTER (\n									DATE_ADD(\n										ld_servicecontracts.due_date,\n										INTERVAL 1 QUARTER\n									)\n								)\n							ELSE\n								YEAR (\n									DATE_ADD(\n										ld_servicecontracts.due_date,\n										INT