INSERT INTO `ld_expensedetailscf` VALUES (1,NULL,1,1.000000,NULL,'¥',NULL,'',0,NULL,NULL,NULL,'','','','',NULL,'',NULL,0,NULL,'',NULL,NULL,NULL,0,NULL,NULL,'','','',NULL,'',NULL,'2024-08-15',NULL,'',NULL,'1.培训\n2.完成测试题\n3.修改第二个账套\n4.帮助手册再讨论，完成整合工作。','','','','','',NULL,NULL,NULL,NULL,NULL,'否',NULL,NULL,NULL,0,0,NULL,NULL,NULL),(2,NULL,1,1.000000,NULL,'¥',NULL,'',0,NULL,NULL,NULL,'','','','',NULL,'',NULL,0,NULL,'',NULL,NULL,NULL,0,NULL,NULL,'','','',NULL,'',NULL,'2024-08-15',NULL,'',NULL,'1.开始进行第一个实施项目。\n2.周六日熟悉发的资料。\n3.操作手册继续修改。\n4.新账套继续修改补充内容。\n5.尝试解答7月部门出的题。','','','','','',NULL,NULL,NULL,NULL,NULL,'否',NULL,NULL,NULL,0,0,NULL,NULL,NULL),(3,NULL,1,1.000000,NULL,'¥',NULL,'',0,NULL,NULL,NULL,'','','','',NULL,'',NULL,0,NULL,'',NULL,NULL,NULL,0,NULL,NULL,'','','',NULL,'',NULL,'2024-08-15',NULL,'',NULL,'1.操作手册排版完成。\n2.练习演讲，解决实际需求问题。\n3.账套修改，完成第二个账套的1/2.\n4.配置鸿安赛维传输接口。\n5.观看视频号，微盘进行学习。','','','','','',NULL,NULL,NULL,NULL,NULL,'否',NULL,NULL,NULL,0,0,NULL,NULL,NULL),(4,NULL,1,1.000000,NULL,'¥',NULL,'',0,NULL,NULL,NULL,'','','','',NULL,'',NULL,0,NULL,'',NULL,NULL,NULL,0,NULL,NULL,'','','',NULL,'',NULL,'2024-08-15',NULL,'',NULL,'1.领取新任务\n2.账套修改任务需要继续\n3.观看视频号，微盘进行学习.\n4.继续学习\n5.如果鸿安赛维配置还有问题，继续修改。','','','','','',NULL,NULL,NULL,NULL,NULL,'否',NULL,NULL,NULL,0,0,NULL,NULL,NULL),(5,NULL,1,1.000000,NULL,'¥',NULL,'',0,NULL,NULL,NULL,'','','','',NULL,'',NULL,0,NULL,'',NULL,NULL,NULL,0,NULL,NULL,'','','',NULL,'',NULL,'2024-08-15',NULL,'',NULL,'1.完成基础任务的情况下，尽可能抽出时间学习微盘内容\n2.完成账套修改任务。\n3.观看视频号，微盘进行学习.\n4.遍历测试继续进行，预计完成客户管理，销售管理两个模块。\n5.如果鸿安赛维配置还有问题，继续修改。','','','','','',NULL,NULL,NULL,NULL,NULL,'否',NULL,NULL,NULL,0,0,NULL,NULL,NULL),(6,NULL,1,1.000000,NULL,'¥',NULL,'',0,NULL,NULL,NULL,'','','','',NULL,'',NULL,0,NULL,'',NULL,NULL,NULL,0,NULL,NULL,'','','',NULL,'',NULL,'2024-08-15',NULL,'',NULL,'1.继续进行第一个实施项目。\n2.学习数据库语言，SQL\n3.操作手册继续修改。\n4.新账套继续修改补充内容。\n5.尝试解答7月部门出的题。','','','','','',NULL,NULL,NULL,NULL,NULL,'否',NULL,NULL,NULL,0,0,NULL,NULL,NULL);
