INSERT INTO `ld_expensescf` VALUES (395857,'',NULL,'','0','1.培训一周时间已经逐步了解灵当CRM系统，明确了本系统的使用方法以及对于针对客户的要求自定义更改模块等。\n2.王楠老师的视频讲解很有逻辑，本周的重点之一。\n3.在本周工作内容里，安排工作有帮助手册的修改和账套的补充内容，其中帮助手册的修改让我对于系统更加了解。\n4.账套的补充实际操作。\n5.帮助手册修改完成近二分之一。\n6.账套一个完全改完，第二个修改四分之三。','1'),(395858,'',NULL,'','0','1.本周将三个行业账套修改完成，基本了解了账套内容。\n2.操作手册修改完成2/3，基本框架修改完成。进一步了解CRM同用账号。\n3.遍历测试进行完成首页等三部分内容，期间有不少问题，在和前辈沟通的过程中，加深学习。\n4.一周的培训，沟通的重要性/试题讲解/企业文化/产品方案，解说等。\n5.一周目前截止进行了四套试题，做题让我了解很多不熟悉的模块等，不理解的地方问前辈，总会耐心解答，受益匪浅。','2'),(395859,'',NULL,'','0','1.上海贰零肆捌物联网技术有限公司助华标准版实施调研，通过调研了解客户需求，本周将大部分内容完成，包括接口excel盖章回传，接口配置，需求管理等\n2.考核演讲等做准备，需要周末练习，将内容熟记，蓝图、公众号视频、系统细节等。\n3.账套修改将电气行业修改完成，半导体等两个账套需要继续修改，将于周末修改完成第一个账套。\n4.操作手册修改完成，只差排版等，预计下周一完成。\n5.遍历测试进行到客户管理模块.\n6.解决客户实际需求问题，包括茂睿芯&amp;助华CRM增强版问题，鸿安赛维问题。','3'),(395860,'',NULL,'','0','1.领取新任务\n2.账套修改任务需要继续\n3.观看视频号，微盘进行学习.\n4.继续学习\n5.如果鸿安赛维配置还有问题，继续修改。','4'),(395861,'',NULL,'','0','1.完成基础任务的情况下，尽可能抽出时间学习微盘内容\n2.完成账套修改任务。\n3.观看视频号，微盘进行学习.\n4.遍历测试继续进行，预计完成客户管理，销售管理两个模块。\n5.如果鸿安赛维配置还有问题，继续修改。','5'),(395862,'',NULL,'','0','1.完善第一个实施项目。\n2.学习数据库语言，SQL\n3.操作手册继续修改。\n4.新账套继续修改补充内容。\n5.尝试解答7月部门出的题。','6');
/*!40000 ALTER TABLE `ld_expensescf` ENABLE KEYS */;
UNLOCK TABLES;

