INSERT INTO `ld_mailmanager_mailrecord` VALUES (9,'网易邮件提醒服务 <notice@qiye.163.com>','yan.liang <yan.liang@convenientpower.com>',NULL,NULL,'2020-04-02 16:40:13','【帐户安全】您的邮箱帐号于2020-04-02_16:40:09在广东省深圳市异地登录(Remote_login_reminder)',NULL,NULL,NULL,NULL,NULL,'AD2AJgANCHGfHH8ZL-YKH4pB',NULL,NULL,NULL,0,0,211,'yan.liang@convenientpower.com',0,'2020-04-02 16:42:33',NULL,'pop'),(9,'网易邮件提醒服务 <notice@qiye.163.com>','yan.liang <yan.liang@convenientpower.com>',NULL,NULL,'2020-04-02 16:40:08','【帐户安全】您的邮箱帐号于2020-04-02_16:40:02在四川省成都市异地登录(Remote_login_reminder)','<!DOCTYPE html>\r\n<html>\r\n<head>\r\n    <meta http-equiv=\"Content-Type\" content=\"text/html; charset=utf-8\" />\r\n    <title></title>\r\n    <style>\r\n        body{background: #f8f8f8}\r\n        .minfo-letter{\r\n            width: 600px;\r\n            margin: 0 auto 30px;\r\n            line-height:21px;\r\n            font-size: 13px;\r\n        }\r\n        .minfo-letter-logo{\r\n            margin: 18px 0 14px 0;\r\n            display:inline-block;\r\n        }\r\n        .minfo-letter-content{\r\n            background: #fff;\r\n            padding: 30px;\r\n            font-size: 13px;\r\n            border:1px solid #ebebeb\r\n        }\r\n        .minfo-letter-content p{\r\n            margin-top:0;\r\n            line-height: 21px;\r\n        }\r\n        .minfo-letter-content p a {\r\n            color: #37a0ff;\r\n        }\r\n        .minfo-letter-content table td>span{\r\n            display: block;\r\n            margin-left: 15px;\r\n            line-height:21px;\r\n            font-weight:bold;\r\n        }\r\n        .minfo-letter-content .minfo-letter-tip{\r\n            color:#666666;\r\n            margin-bottom: 7px;\r\n            line-height:21px;\r\n        }\r\n        .icon-dingwei003{\r\n            width: 30px;\r\n            height: 30px;\r\n            display: block;\r\n            background-size: contain;\r\n            background-image: url(\'data:image/png;base64,\');\r\n        }\r\n        a{ text-decoration: none;}\r\n    </style>\r\n</head>\r\n<body>\r\n	 <div class=\"minfo-letter\">\r\n        <img class=\"minfo-letter-logo\" src=\"http://qiye.163.com/logo/logo.gif\" alt=\"网易企业邮箱\">\r\n        <div class=\"minfo-letter-content\">\r\n            <p>尊敬的用户：</p>\r\n            <p>您的邮箱帐号 (yan.liang<span>@</span>convenientpower.com) 有以下成功登录记录，与您上一次登录地点不符：</p>\r\n            <table style=\"margin: 25px 0;font-size: 13px;\">\r\n                <tr>\r\n                    <td>\r\n                        <i class=\"icon-dingwei003\" style=\"font-size: 30px;\"></i>\r\n                    </td>\r\n                    <td>\r\n                        <span>2020年04月02日 星期四 16时40分02秒</span>\r\n                        <span>四川省成都市 (171.221.206.240)</span>\r\n                        <span>客户端登录</span>\r\n                    </td>\r\n                </tr>\r\n            </table>\r\n            <p style=\"margin-bottom: 0;font-weight: bold\">如非本人操作？</p>\r\n            <p style=\"margin-bottom: 0;\">为了保证邮箱的安全，请您尽快<a href=\" https://qiye.163.com/login/\">登录网页端邮箱</a>修改密码。</p>\r\n            <p>通常网络运营商会分配动态IP用于上网，故若出现陌生登录IP，可查询您所用设备的IP地址，或检查邮箱有无异常收发信记录，从而判断是否是本人操作。</p>\r\n            <p class=\"minfo-letter-tip\" style=\"margin-top: 15px;\">提示：</p>\r\n            <p class=\"minfo-letter-tip\">(1). 查询设备IP地址方法：在您所用设备上打开浏览器的搜索页面，输入”IP”即可在搜索记录中看到本机IP地址。</p>\r\n            <p class=\"minfo-letter-tip\">(2). 如需关闭提醒或修改提醒方式，请登录网页端邮箱 <a href=\" https://qiye.163.com/login/\">https://qiye.163.com/login/</a> ，在 ”设置-安全提醒-异地登录提醒”功能下进行操作。</p>\r\n            <p class=\"minfo-letter-tip\">(3). 修改密码方法：详见<a href=\"https://qiye.163.com/help/8b4842.html\" target=\"_blank\">https://qiye.163.com/help/8b4842.html</a></p>\r\n            <p style=\"margin-top: 20px;margin-bottom: 20px\">网易企业服务</p>\r\n            <p>Dear Customer，</p>\r\n            <p>Your email account(yan.liang<span>@</span>convenientpower.com) has the following successful login record, which does not match your last login location:</p>\r\n            <table style=\"margin: 25px 0;font-size: 13px;\">\r\n                <tr>\r\n                    <td>\r\n                        <i class=\"icon-dingwei003\" style=\"font-size: 30px;\"></i>\r\n                    </td>\r\n                    <td>\r\n                        <span>Thu,Apr 02,2020 16:40:02</span>\r\n                        <span>Chengdu,Sichuan (171.221.206.240)</span>\r\n                        <span>Client login</span>\r\n                    </td>\r\n                </tr>\r\n            </table>\r\n            <p style=\"margin-bottom: 0;font-weight: bold\">If it is not your own operation？</p>\r\n            <p style=\"margin-bottom: 0;\">In order to ensure the security of your email, please <a href=\" https://qiye.163.com/login/\"> log in to the Webmail</a> as soon as possible to change the password. </p>\r\n            <p>Usually, the network operator will assign dynamic IP to access the Internet. Therefore, if there is a strange login IP, you can check the IP of the device you are using, or check the mailbox for abnormal sending and receiving records to judge whether it is your operation.</p>\r\n            <p class=\"minfo-letter-tip\" style=\"margin-top: 15px;\">Tips:</p>\r\n            <p class=\"minfo-letter-tip\">(1). Query the device IP method: Open the browser’s search page on your device and enter the “IP” to see the local IP address in the search record.</p>\r\n            <p class=\"minfo-letter-tip\">(2). To close the reminder or modify the reminder method, please log in to the Webmail at <a href=\" https://qiye.163.com/login/\">https://qiye.163.com/login/</a> and operate under the “Settings - Security Reminder - Remote Login Reminder” function.</p>\r\n            <p class=\"minfo-letter-tip\">(3). Change password method: <a href=\"https://qiye.163.com/help/8b4842.html\" target=\"_blank\">https://qiye.163.com/help/8b4842.html</a></p>\r\n            <p style=\"margin-top: 20px;margin-bottom: 0\">NetEase Enterprise Service</p>\r\n        </div>\r\n    </div>\r\n</body>\r\n</html>',NULL,NULL,NULL,NULL,'APUAWwA1CCyf2H9JL1MIaKpa',1,NULL,NULL,1,0,212,'yan.liang@convenientpower.com',0,'2020-04-02 16:42:35',NULL,'pop'),(9,'yunqiang.chen@convenientpower.com <yunqiang.chen@convenientpower.com>','cps_all <cps_all@convenientpower.com>,hairong.zhou<hairong.zhou@convenientpower.com>',NULL,NULL,'2020-04-02 14:45:17','新人介绍--OPS TE/周海荣',NULL,NULL,NULL,NULL,NULL,'AFYAPAAGCIefsliKeleSiqpt',NULL,NULL,NULL,0,0,213,'yan.liang@convenientpower.com',0,'2020-04-02 16:42:36',NULL,'pop'),(9,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'ADcAwQBjCHSf0ER5Uo*JUar8',NULL,NULL,NULL,0,0,214,'yan.liang@convenientpower.com',0,'2020-04-02 16:42:36',NULL,'pop'),(9,'Felix@villon.com.cn <Felix@villon.com.cn>','xiaoyong.liu <xiaoyong.liu@convenientpower.com>',NULL,NULL,'2020-04-02 11:42:52','Re: RE：代理商客户报备—汇能',NULL,NULL,NULL,NULL,NULL,'AAAA-gChCAOfIx7nroUWGKpM',NULL,NULL,NULL,0,0,215,'yan.liang@convenientpower.com',0,'2020-04-02 16:43:37',NULL,'pop'),(9,'yan.liang@convenientpower.com','lianwu.zhang@convenientpower.com;','hui.yao@convenientpower.com;',NULL,'2020-04-02 16:45:19','拜访报告','<p style=\"font-family: 微软雅黑; font-size: medium; white-space: normal;\">&nbsp;&nbsp;</p><p style=\"font-family: 微软雅黑; font-size: medium; white-space: normal;\">&nbsp;&nbsp;</p><h1 style=\"font-family: 微软雅黑; white-space: normal; text-align: center;\">&nbsp;拜访报告</h1><hr style=\"font-family: 微软雅黑; font-size: medium; white-space: normal;\"/><p style=\"font-family: 微软雅黑; font-size: medium; white-space: normal;\">&nbsp;</p><table bordercolor=\"#000000\" cellpadding=\"3\" cellspacing=\"0\" data-sort=\"sortDisabled\" width=\"1331\" style=\"width: 1256px;\"><tbody><tr class=\"firstRow\"><td width=\"232\" style=\"word-break: break-all; border-color: rgb(63, 63, 63);\">企业名称</td><td width=\"418\" style=\"border-color: rgb(63, 63, 63);\">深圳市爱图仕影像器材有限公司</td><td width=\"232\" style=\"word-break: break-all; border-color: rgb(63, 63, 63);\">拜访日期</td><td width=\"417\" style=\"border-color: rgb(63, 63, 63);\">2020-03-31 19:54:50</td></tr><tr><td width=\"89\" style=\"word-break: break-all; border-color: rgb(63, 63, 63);\">代理联系人</td><td width=\"299\" style=\"border-color: rgb(63, 63, 63);\"><br/></td><td width=\"90\" style=\"word-break: break-all; border-color: rgb(63, 63, 63);\">下次回访日期</td><td width=\"305\" style=\"word-break: break-all; border-color: rgb(63, 63, 63);\"><br/></td></tr><tr><td width=\"89\" style=\"word-break: break-all; border-color: rgb(63, 63, 63);\">是否有销售机会</td><td width=\"299\" style=\"border-color: rgb(63, 63, 63);\">否</td><td width=\"90\" style=\"word-break: break-all; border-color: rgb(63, 63, 63);\">销售负责人</td><td width=\"305\" style=\"word-break: break-all; border-color: rgb(63, 63, 63);\">梁燕</td></tr><tr><td width=\"89\" style=\"word-break: break-all; border-color: rgb(63, 63, 63);\">拜访记录</td><td colspan=\"3\" style=\"border-color: rgb(63, 63, 63);\"><p>拜访目的：目前项目进度及问题点了解<br/>拜访人员：产品经理周向军，项目经理常傲俊，工程师杨工<br/>项目信息：TX 型号8012， RX 所用型号4037，项目之前使用美芯晟，因有断充及无法充满电问题考虑更换易冲；RX 试产500PC（尚未上线），若上线测试OK， 则切换易充；目前暂无新项目开案<br/>订单信息：TX 已下订单12K, 爱图仕目前尚有美芯晟RX 库存50K, 使用完后再使用易冲方案，预计每月需求20K左右（需确认疫情影响，去年出货200K）<br/>市场讯息：同类产品客户为神牛及南光<br/>会议内容：分析TX 成品充电不灵敏现象，现场分析为结构问题（线圈未在正中，有便宜；壳体厚度导致线圈距离为5毫米左右），介绍无线充充电原理及结构注意事项，并提供改善建议，得到客户认同</p></td></tr><tr><td colspan=\"1\" rowspan=\"1\" width=\"undefined\" style=\"word-break: break-all; border-color: rgb(63, 63, 63);\">代办事项<br/></td><td colspan=\"3\" rowspan=\"1\" style=\"word-break: break-all; border-color: rgb(63, 63, 63);\"><p>提供之前要求的TX 失效分析报告</p><p>跟进500PC 试产结果</p><p>跟进后续订单</p><p>寻找市场同类产品客户</p><p>&nbsp;</p><p></p><p></p><p></p><p></p></td></tr></tbody></table><p style=\"font-family: 微软雅黑; font-size: medium; white-space: normal;\">&nbsp;</p><p><br/></p>',NULL,NULL,NULL,NULL,'',1,NULL,NULL,1,0,216,'yan.liang@convenientpower.com',0,'2020-04-02 16:45:19',NULL,'smtp'),(9,'yan.li@convenientpower.com <yan.li@convenientpower.com>','pindan.yin <pindan.yin@conveni