r\n/* Font Definitions */\r\n@font-face\r\n	{font-family:宋体;\r\n	panose-1:2 1 6 0 3 1 1 1 1 1;}\r\n@font-face\r\n	{font-family:\"Cambria Math\";\r\n	panose-1:2 4 5 3 5 4 6 3 2 4;}\r\n@font-face\r\n	{font-family:Calibri;\r\n	panose-1:2 15 5 2 2 2 4 3 2 4;}\r\n@font-face\r\n	{font-family:微软雅黑;\r\n	panose-1:2 11 5 3 2 2 4 2 2 4;}\r\n@font-face\r\n	{font-family:\"\\@微软雅黑\";\r\n	panose-1:2 11 5 3 2 2 4 2 2 4;}\r\n@font-face\r\n	{font-family:\"\\@宋体\";\r\n	panose-1:2 1 6 0 3 1 1 1 1 1;}\r\n/* Style Definitions */\r\np.MsoNormal, li.MsoNormal, div.MsoNormal\r\n	{margin:0cm;\r\n	margin-bottom:.0001pt;\r\n	font-size:11.0pt;\r\n	font-family:\"Calibri\",sans-serif;}\r\na:link, span.MsoHyperlink\r\n	{mso-style-priority:99;\r\n	color:#0563C1;\r\n	text-decoration:underline;}\r\na:visited, span.MsoHyperlinkFollowed\r\n	{mso-style-priority:99;\r\n	color:#954F72;\r\n	text-decoration:underline;}\r\nspan.EmailStyle17\r\n	{mso-style-type:personal-compose;\r\n	font-family:\"Calibri\",sans-serif;\r\n	color:windowtext;}\r\n.MsoChpDefault\r\n	{mso-style-type:export-only;}\r\n@page WordSection1\r\n	{size:612.0pt 792.0pt;\r\n	margin:72.0pt 90.0pt 72.0pt 90.0pt;}\r\ndiv.WordSection1\r\n	{page:WordSection1;}\r\n--></style><!--[if gte mso 9]><xml>\r\n<o:shapedefaults v:ext=\"edit\" spidmax=\"1026\" />\r\n</xml><![endif]--><!--[if gte mso 9]><xml>\r\n<o:shapelayout v:ext=\"edit\">\r\n<o:idmap v:ext=\"edit\" data=\"1\" />\r\n</o:shapelayout></xml><![endif]--></head><body lang=EN-US link=\"#0563C1\" vlink=\"#954F72\"><div class=WordSection1><p class=MsoNormal>Dear All<o:p></o:p></p><p class=MsoNormal><span lang=ZH-CN style=\'font-family:宋体\'>很高兴给大家介绍</span>digital team<span lang=ZH-CN style=\'font-family:宋体\'>的新同事，大家多多支持。下面是杨帆的个人简介</span><o:p></o:p></p><p class=MsoNormal><o:p>&nbsp;</o:p></p><p class=MsoNormal><span lang=ZH-CN style=\'font-size:10.5pt;font-family:\"微软雅黑\",sans-serif;color:#111F2C;background:white\'>”我叫杨帆，四川巴中人，</span><span style=\'font-size:10.5pt;font-family:\"微软雅黑\",sans-serif;color:#111F2C;background:white\'>2018<span lang=ZH-CN>年</span>6<span lang=ZH-CN>月毕业于四川大学控制理论与控制工程专业。毕业后在中兴通讯从事数字</span>IC<span lang=ZH-CN>前端开发，到目前为止参与过两个项目，均为通信芯片的前端设计。在无线冲这方面的经验很少，请大家多多指教。”</span></span><o:p></o:p></p><p class=MsoNormal><o:p>&nbsp;</o:p></p><p class=MsoNormal>Best,<o:p></o:p></p><p class=MsoNormal>Alan<o:p></o:p></p><p class=MsoNormal><o:p>&nbsp;</o:p></p><p class=MsoNormal><o:p>&nbsp;</o:p></p></div></body></html>',NULL,NULL,NULL,NULL,'AGkAMAChCP5SeBoty0L244rQ',1,NULL,NULL,1,0,546,'rong.chen@convenientpower.com',0,'2020-06-01 18:12:36',NULL,'pop'),(32,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'AAEA*wDMCFvZpUStdyR39Kro',NULL,NULL,NULL,0,0,547,'cheng.liu@convenientpower.com',0,'2020-06-01 18:12:36',NULL,'pop'),(25,'vickers.zeng@convenientpower.com <lin.zeng@convenientpower.com>','XiaoYong Liu <xiaoyong.liu@convenientpower.com>',NULL,NULL,'2020-05-21 11:33:17','回复: QI认证 powerbank P105W 客户华美  终端mophie',NULL,NULL,NULL,NULL,NULL,'ABAAewAlCILRrcTLCZUm6aqf',NULL,NULL,NULL,0,0,548,'rong.chen@convenientpower.com',0,'2020-06-01 18:12:37',NULL,'pop'),(32,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'AFIAdgA5CGrYj*uEdwkquapl',NULL,NULL,NULL,0,0,549,'cheng.liu@convenientpower.com',0,'2020-06-01 18:12:37',NULL,'pop'),(25,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'AO*AVgACCP5RCJyFvvti74pJ',NULL,NULL,NULL,0,0,550,'rong.chen@convenientpower.com',0,'2020-06-01 18:12:38',NULL,'pop'),(25,'jack pan <jack.pan@convenientpower.com>','ge.huang@convenientpower.com <ge.huang@convenientpower.com>',NULL,NULL,'2020-05-20 16:16:04','Re:_新人介绍--Layout_team：王鑫',NULL,NULL,NULL,NULL,NULL,'AHAAywB8CAXQwvrdOggpSKoj',NULL,NULL,NULL,0,0,551,'rong.chen@convenientpower.com',0,'2020-06-01 18:12:38',NULL,'pop'),(25,'ge.huang@convenientpower.com <ge.huang@convenientpower.com>','CPS ALL <cps_all@convenientpower.com>','\"Xin Wang\" <xin.wang@convenientpower.com>',NULL,'2020-05-20 15:34:18','新人介绍--Layout team：王鑫','<html><head><meta http-equiv=\"content-type\" content=\"text/html; charset=GB2312\"><style>body { line-height: 1.5; }p { margin-top: 0px; margin-bottom: 0px; }body { font-size: 10.5pt; font-family: 微软雅黑; color: rgb(0, 0, 0); line-height: 1.5; }</style></head><body>\n<div><span></span><div>Dear all，</div><div><br></div><div>Layout team今天新加入一名版图工程师----王鑫。他有两年多的版图经验，希望在易冲可以和大家一起学习、成长。</div><div>以下是他的自我介绍：</div></div><div><span style=\"background-color: rgba(0, 0, 0, 0);\"><font color=\"#0000ff\">我是2018年毕业于电子科技大学成都学院集成电路设计与集成系统专业的王鑫。从事模拟版图设计已经两年多，之前做过一年的基于电源管理类芯片版图，一年的精密运放、高压基准源的芯片版图。很高兴加入CPS这个大家庭，并任职芯片版图设计岗位。</font></span></div>\n<div><br></div><div>热烈欢迎王鑫加入！</div><div><br></div><hr style=\"width: 210px; height: 1px;\" color=\"#b5c4df\" size=\"1\" align=\"left\">\n<div><span><div style=\"MARGIN: 10px; FONT-FAMILY: verdana; FONT-SIZE: 10pt\"><div style=\"font-family: 微软雅黑; font-size: 15px;\"><font face=\"Arial\">Thanks.</font></div><div style=\"font-family: 微软雅黑; font-size: 15px;\"><font face=\"Arial\">Best regards,</font></div><div style=\"font-family: 微软雅黑; font-size: 15px;\"><font face=\"Arial\">Gene</font></div><div style=\"font-family: 微软雅黑; font-size: 15px;\"><img src=\"storage/mail/rong.chen@convenientpower.com/cid/15575_15575_convenient(03-30-17-51-59)535996.png\" border=\"0\" style=\"max-width: 100%; height: auto !important;\"></div><div style=\"font-family: 微软雅黑;\"><span style=\"font-family: Arial;\">Gene Huang</span><b style=\"font-family: Arial; line-height: normal; text-align: justify;\"><span lang=\"EN-US\">&nbsp;</span></b><span lang=\"EN-US\" style=\"font-family: Arial; line-height: normal; text-align: justify;\">| Layout Engineer</span></div><div style=\"font-family: 微软雅黑;\"><font face=\"Arial\"><span lang=\"EN-US\" style=\"line-height: 18pt; text-align: justify;\">Tel: +86&nbsp;</span><span lang=\"EN-US\" style=\"line-height: 18pt; text-align: justify;\">18980011771</span></font></div><div style=\"font-family: 微软雅黑;\"><p class=\"MsoNormal\" style=\"margin: 0cm 0cm 0.0001pt; text-align: justify; lin