d 15 (filtered medium)\"><style><!--\r\n/* Font Definitions */\r\n@font-face\r\n	{font-family:宋体;\r\n	panose-1:2 1 6 0 3 1 1 1 1 1;}\r\n@font-face\r\n	{font-family:\"Cambria Math\";\r\n	panose-1:2 4 5 3 5 4 6 3 2 4;}\r\n@font-face\r\n	{font-family:Calibri;\r\n	panose-1:2 15 5 2 2 2 4 3 2 4;}\r\n@font-face\r\n	{font-family:微软雅黑;\r\n	panose-1:2 11 5 3 2 2 4 2 2 4;}\r\n@font-face\r\n	{font-family:\"\\@微软雅黑\";\r\n	panose-1:2 11 5 3 2 2 4 2 2 4;}\r\n@font-face\r\n	{font-family:\"\\@宋体\";\r\n	panose-1:2 1 6 0 3 1 1 1 1 1;}\r\n/* Style Definitions */\r\np.MsoNormal, li.MsoNormal, div.MsoNormal\r\n	{margin:0cm;\r\n	margin-bottom:.0001pt;\r\n	font-size:11.0pt;\r\n	font-family:\"Calibri\",sans-serif;}\r\na:link, span.MsoHyperlink\r\n	{mso-style-priority:99;\r\n	color:#0563C1;\r\n	text-decoration:underline;}\r\na:visited, span.MsoHyperlinkFollowed\r\n	{mso-style-priority:99;\r\n	color:#954F72;\r\n	text-decoration:underline;}\r\nspan.EmailStyle17\r\n	{mso-style-type:personal-compose;\r\n	font-family:\"Calibri\",sans-serif;\r\n	color:windowtext;}\r\n.MsoChpDefault\r\n	{mso-style-type:export-only;\r\n	font-family:\"Calibri\",sans-serif;}\r\n@page WordSection1\r\n	{size:612.0pt 792.0pt;\r\n	margin:72.0pt 90.0pt 72.0pt 90.0pt;}\r\ndiv.WordSection1\r\n	{page:WordSection1;}\r\n--></style><!--[if gte mso 9]><xml>\r\n<o:shapedefaults v:ext=\"edit\" spidmax=\"1026\" />\r\n</xml><![endif]--><!--[if gte mso 9]><xml>\r\n<o:shapelayout v:ext=\"edit\">\r\n<o:idmap v:ext=\"edit\" data=\"1\" />\r\n</o:shapelayout></xml><![endif]--></head><body lang=EN-US link=\"#0563C1\" vlink=\"#954F72\"><div class=WordSection1><p class=MsoNormal>Dear All<o:p></o:p></p><p class=MsoNormal><span lang=ZH-CN style=\'font-family:宋体\'>很高兴给大家介绍一位新同事——何泉初，他负责芯片数字电路的设计工作，希望大家多帮助和支持他尽快融入公司。下面是他的自我介绍：</span><o:p></o:p></p><p class=MsoNormal><o:p>&nbsp;</o:p></p><p class=MsoNormal><span lang=ZH-CN style=\'font-family:宋体\'>“</span><span lang=ZH-CN style=\'font-size:10.5pt;font-family:\"微软雅黑\",sans-serif;color:#111F2C;background:white\'>大家好，我是何泉初，来自成都双流，很高兴能加入这个年轻有活力的团队。我本科毕业于电子科技大学电子信息工程专业，硕士毕业于新加坡南洋理工大学集成电路设计专业。此前在新加坡联发科分公司有过一年时间的实习经验，负责逻辑综合和脚本整合的工作。平时我的爱好比较广泛：唱歌，打篮球，弹钢琴，还有玩游戏。我是各种</span><span style=\'font-size:10.5pt;font-family:\"微软雅黑\",sans-serif;color:#111F2C;background:white\'>FPS<span lang=ZH-CN>游戏的脑残粉，偶尔玩玩王者荣耀。希望在未来的日子里能和大家打成一片，也提前感谢大家在未来的日子里工作上给我提供的帮助！谢谢大家！约饭的时候记得喊我，谢谢！</span>VX/TEL<span lang=ZH-CN>：</span>13980059216<span lang=ZH-CN>。</span></span><span lang=ZH-CN style=\'font-family:宋体\'>”</span><o:p></o:p></p><p class=MsoNormal><o:p>&nbsp;</o:p></p><p class=MsoNormal><o:p>&nbsp;</o:p></p><p class=MsoNormal>Best,<o:p></o:p></p><p class=MsoNormal>Alan<o:p></o:p></p><p class=MsoNormal><o:p>&nbsp;</o:p></p><p class=MsoNormal><o:p>&nbsp;</o:p></p></div></body></html>',NULL,NULL,NULL,NULL,'AEQA7gAICHfkTopoEHCNaKqx',1,NULL,NULL,1,0,677,'rong.chen@convenientpower.com',0,'2020-06-10 14:37:34',NULL,'pop'),(25,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'AN6A1wBKCNPkil1BCO*HMKq9',NULL,NULL,NULL,0,0,678,'rong.chen@convenientpower.com',0,'2020-06-10 14:37:34',NULL,'pop'),(25,'Mike Chan <mike.chan@convenientpower.com>','卢燕陵 <yanling.lu@convenientpower.com>,陈榕<rong.chen@convenientpower.com>,Vickers.Zeng<vickers.zeng@convenientpower.com>',NULL,NULL,'2020-06-08 16:17:36','Fwd: Mophie Sample return HK20060348',NULL,NULL,NULL,NULL,NULL,'AI2AbADeCDXk5-fjRMeDpaoh',NULL,NULL,NULL,0,0,679,'rong.chen@convenientpower.com',0,'2020-06-10 14:37:35',NULL,'pop'),(25,'yanling.lu@convenientpower.com <yanling.lu@convenientpower.com>','rong.chen@convenientpower.com <rong.chen@convenientpower.com>,jian.li<jian.li@convenientpower.com>',NULL,NULL,'2020-06-08 13:52:34','Fw: Re: Vent Mount 2020 EE Spec',NULL,NULL,NULL,NULL,NULL,'ABcAtABgCDfkaRNDgg6wIqpk',NULL,NULL,NULL,0,0,680,'rong.chen@convenientpower.com',0,'2020-06-10 14:37:36',NULL,'pop'),(25,'网易邮件提醒服务 <notice@qiye.163.com>','rong.chen <rong.chen@convenientpower.com>',NULL,NULL,'2020-06-08 11:33:30','【帐户安全】您的邮箱帐号于2020-06-08_11:33:03在浙江省杭州市异地登录