/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `ld_minusjobbillscf` (
  `minusjobbillid` int(19) NOT NULL DEFAULT '0',
  `sytx` varchar(20) DEFAULT NULL,
  `synj` varchar(20) DEFAULT NULL,
  PRIMARY KEY (`minusjobbillid`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8;
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `ld_minusjobbillscf`
--

LOCK TABLES `ld_minusjobbillscf` WRITE;
