ccount.bill_state,\"\"),IFNULL(ld_account.bill_city,\"\"),IFNULL(ld_account.bill_area,\"\"),ld_account.bill_street) AS tmp_value FROM ld_troubletickets INNER JOIN ld_account ON ld_account.accountid = ld_troubletickets.accountid WHERE ld_account.deleted = 0 AND ld_troubletickets.ticketid = {Record.ID}','no'),(203,22,20,0,1,0,1,27,'all','quote_id',20,NULL,NULL,NULL,'yes','','',NULL,0.0000,'',NULL,NULL,NULL,NULL,NULL,'yes',NULL,NULL,NULL,NULL,'no'),(204,22,139,0,0,1,2,27,'all','quote_id',5,0,0,0,'yes',NULL,NULL,'yes',0.0000,NULL,'no',0,NULL,NULL,NULL,'yes',NULL,NULL,NULL,NULL,'no'),(205,20,141,0,1,0,1,25,'all',NULL,20,0,0,0,'yes',NULL,NULL,'yes',0.0000,NULL,'no',0,NULL,NULL,NULL,'yes',NULL,NULL,NULL,NULL,'no'),(206,67,21,0,0,0,7,84,'all',NULL,5,0,0,0,'no',NULL,NULL,'yes',0.0000,NULL,'no',0,NULL,NULL,NULL,'yes',NULL,NULL,NULL,NULL,'no'),(207,142,26,0,0,0,7,116,'permit',NULL,5,0,0,1,'yes',NULL,NULL,'yes',0.0000,NULL,'no',0,NULL,NULL,NULL,'yes',NULL,NULL,'sql','SELECT CONCAT(IFNULL(ld_account.bill_state,\"\"),IFNULL(ld_account.bill_city,\"\"),IFNULL(ld_account.bill_area,\"\"),ld_account.bill_street) AS address\r\nFROM ld_account\r\nWHERE ld_account.deleted = 0 AND accountid = ?\r\nUNION \r\nSELECT CONCAT(IFNULL(ld_account.bill_state,\"\"),IFNULL(ld_account.bill_city,\"\"),IFNULL(ld_account.bill_area,\"\"),ld_account.bill_street) AS address\r\nFROM ld_contactdetails\r\nINNER JOIN ld_account ON ld_account.accountid = ld_contactdetails.accountid\r\nWHERE ld_account.deleted = 0 AND ld_contactdetails.contactid = ?\r\nUNION \r\nSELECT CONCAT(IFNULL(ld_account.bill_state,\"\"),IFNULL(ld_account.bill_city,\"\"),IFNULL(ld_account.bill_area,\"\"),ld_account.bill_street) AS address\r\nFROM ld_contactrecords\r\nINNER JOIN ld_account ON ld_account.accountid = ld_contactrecords.accountid\r\nWHERE ld_account.deleted = 0 AND ld_contactrecords.contactrecordID = ?\r\nUNION \r\nSELECT CONCAT(IFNULL(ld_account.bill_state,\"\"),IFNULL(ld_account.bill_city,\"\"),IFNULL(ld_account.bill_area,\"\"),ld_account.bill_street) AS address\r\nFROM ld_potential\r\nINNER JOIN ld_account ON ld_account.accountid = ld_potential.accountid\r\nWHERE ld_account.deleted = 0 AND ld_potential.potentialid = ?\r\nUNION \r\nSELECT CONCAT(IFNULL(ld_account.bill_state,\"\"),IFNULL(ld_account.bill_city,\"\"),IFNULL(ld_account.bill_area,\"\"),ld_account.bill_street) AS address\r\nFROM ld_troubletickets\r\nINNER JOIN ld_account ON ld_account.accountid = ld_troubletickets.accountid\r\nWHERE ld_account.deleted = 0 AND ld_troubletickets.ticketid = ?\r\nUNION \r\nSELECT CONCAT(IFNULL(ld_account.bill_state,\"\"),IFNULL(ld_account.bill_city,\"\"),IFNULL(ld_account.bill_area,\"\"),ld_account.bill_street) AS address\r\nFROM ld_project\r\nINNER JOIN ld_account ON ld_account.accountid = ld_project.accountid\r\nWHERE ld_account.deleted = 0 AND ld_project.projectid = ?\nUNION\nSELECT CONCAT(ld_leads.bill_state,ld_leads.bill_city,IFNULL(ld_leads.bill_area,\"\"),ld_leads.bill_street) AS address\nFROM ld_leads\nWHERE deleted = 0 AND leadsid = ?','no'),(208,48,22,0,NULL,0,1,54,'all',NULL,5,0,0,0,'yes',NULL,NULL,'yes',0.0000,NULL,'no',0,NULL,NULL,NULL,'yes',NULL,NULL,NULL,NULL,'no'),(209,48,37,0,1,0,2,54,'all',NULL,5,0,0,0,'yes',NULL,NULL,'yes',0.0000,NULL,'no',0,NULL,NULL,NULL,'yes',NULL,NULL,NULL,NULL,'no'),(210,155,156,1,0,0,4,145,'all',NULL,5,NULL,NULL,0,'yes',NULL,NULL,'yes',0.0000,NULL,'no',0,NULL,NULL,NULL,'yes',NULL,NULL,NULL,NULL,'no'),(211,156,155,0,0,0,1,146,'all',NULL,50,0,0,0,'yes',NULL,NULL,'yes',0.0000,NULL,'no',0,NULL,NULL,NULL,'yes',NULL,NULL,NULL,NULL,'no'),(212,122,153,0,0,0,2,59,'permit','',10,0,0,0,'no',NULL,NULL,'yes',0.0000,NULL,'no',0,NULL,NULL,NULL,'yes',NULL,NULL,NULL,NULL,'no'),(213,122,144,0,0,0,3,59,'permit',NULL,10,0,0,0,'no',NULL,NULL,'yes',0.0000,NULL,'no',0,NULL,NULL,NULL,'yes',NULL,NULL,NULL,NULL,'no'),(214,169,22,0,0,0,1,168,'all',NULL,5,0,0,0,'no',NULL,NULL,'yes',0.0000,NULL,'no',0,NULL,NULL,NULL,'yes',NULL,NULL,NULL,NULL,'no'),(215,169,37,0,0,0,2,168,'all',NULL,5,