INSERT INTO `ld_organizationdetails_brief` VALUES (1,1,'成立于2008年，总部位于上海，在上海、北京、深圳、苏州、南京、杭州、济南、武汉、合肥等地设立了分支机构和服务中心。灵当软件专注于CRM客户关系管理软件和SAAS云服务应用的开发、销售、运营和服务，致力于为客户提供CRM行业解决方案，通过平台化定制和流程自定义满足客户个性化管理需求，是个性化CRM倡导者。','','text'),(2,1,'“灵当”含义：灵活配置，口碑响当当','','text');
