/*!50003 CREATE*/ /*!50017 */ /*!50003 TRIGGER `yc_reset_outorderinfo_outorderupdate` BEFORE UPDATE ON `ld_outboundorder` FOR EACH ROW BEGIN 

	IF @disable_triggers IS NULL THEN
		SET NEW.receivable_balance=ROUND(IFNULL(NEW.total,0)-IFNULL(NEW.received_amount,0),2);
		SET NEW.xiaoshou_total=ROUND((
			SELECT
				SUM(b.sf19302)
			FROM ld_outboundorderdetail a
			LEFT JOIN ld_outboundorderdetailscf b ON b.lineitem_id=a.lineitem_id
			WHERE a.id=NEW.out_id
		),2);

		IF IFNULL(NEW.cf_4801,'')='' THEN
			IF NEW.currency_id=1 THEN
				SET NEW.cf_4801=NEW.cf_4700;
			ELSE
				SET NEW.cf_4801=(SELECT accountname FROM ld_account WHERE accountid=NEW.accountid);
			END IF;
		END IF;

		UPDATE ld_outboundorder a
		LEFT JOIN ld_outboundordercf b ON b.out_id=a.out_id
		LEFT JOIN ld_outboundorderdetail c ON c.id=a.out_id
		LEFT JOIN ld_outboundorderdetailscf d ON d.lineitem_id=c.lineitem_id
		SET d.sf7275=b.cf_4716
		WHERE a.out_id=NEW.out_id
			AND IFNULL(d.sf7275,0)=0;

		UPDATE ld_outboundorder a
		LEFT JOIN ld_outboundorderdetail b ON b.id=a.out_id
		LEFT JOIN ld_outboundorderdetailscf c ON c.lineitem_id=b.lineitem_id
		SET 
			b.listprice=ROUND((
				CASE
					WHEN IFNULL(b.listprice,0)=0 AND a.currency_id=7 THEN b.taxprice
					WHEN IFNULL(b.listprice,0)=0 AND a.currency_id=1 THEN ROUND(b.taxprice/1.13,6)
					ELSE b.listprice
				END 
				),8),
			c.sf18972=ROUND((
				CASE
					WHEN IFNULL(c.sf18972,0)=0 AND a.currency_id=7 THEN ROUND(b.taxprice/0.9,6)
					WHEN IFNULL(c.sf18972,0)=0 AND a.currency_id=1 THEN ROUND(b.taxprice/1.13,6)
					ELSE c.sf18972
				END 
				),8),
			c.sf19302=ROUND(b.quantity*c.sf7275*(
				CASE
					WHEN IFNULL(c.sf19302,0)=0 AND a.currency_id=7 THEN ROUND(b.taxprice/0.9,6)
					WHEN IFNULL(c.sf19302,0)=0 AND a.currency_id=1 THEN ROUND(b.taxprice/1.13,6)
					ELSE c.sf18972
				END 
				),8),
                                         b.list_amount=ROUND(b.quantity*(
				CASE
					WHEN IFNULL(b.listprice,0)=0 AND a.currency_id=7 THEN b.taxprice
					WHEN IFNULL(b.listprice,0)=0 AND a.currency_id=1 THEN ROUND(b.taxprice/1.13,6)
					ELSE b.listprice
				END 
				),8),
			c.sf14274=ROUND(1/(c.sf7275+0),4)
		WHERE a.out_id=NEW.out_id;
	END IF;
		
END */;;
