INSERT INTO `ld_productcf` VALUES (395502,NULL,0,'',0,'','','',0,0,2000.000000,0,'',1500.000000,0,0,'','','','',2000.000000,2000.000000,0,'','','','','','','<p>负责计算和控制任务的核心组件，广泛应用于计算机和智能设备中。</p>',0,'',''),(395503,NULL,0,'',0,'','','',0,0,2000.000000,0,'',1500.000000,0,0,'','','','',2000.000000,2000.000000,0,'','','','','','','<p>一种常用的线性集成电路，用于放大和处理模拟信号。</p>',0,'',''),(395504,NULL,0,'',0,'','','',0,0,2000.000000,0,'',1500.000000,0,0,'','','','',2000.000000,2000.000000,0,'','','','','','','<p>用于开关和放大信号，广泛应用于电源管理和信号调节中。</p>',0,'',''),(395505,NULL,0,'',0,'','','',0,0,2000.000000,0,'',1500.000000,0,0,'','','','',2000.000000,2000.000000,0,'','','','','','','<p>具有低正向电压降和高速开关特性的二极管，用于高频和低电压应用。</p>',0,'',''),(395506,NULL,0,'',0,'','','',0,0,2000.000000,0,'',1500.000000,0,0,'','','','',2000.000000,2000.000000,0,'','','','','','','<p>用于光电探测和光纤通信中的光信号接收。</p>',0,'',''),(395507,NULL,0,'',0,'','','',0,0,2000.000000,0,'',1500.000000,0,0,'','','','',2000.000000,2000.000000,0,'','','','','','','<p>一种广泛使用的小信号NPN晶体管，用于放大和开关电路。</p>',0,'',''),(395508,NULL,0,'',0,'','','',0,0,2000.000000,0,'',1500.000000,0,0,'','','','',2000.000000,2000.000000,0,'','','','','','','<p>专门用于处理数字信号的集成电路，用于音频处理、图像处理等应用。</p>',0,'',''),(395509,NULL,0,'',0,'','','',0,0,2000.000000,0,'',1500.000000,0,0,'','','','',2000.000000,2000.000000,0,'','','','','','','<p>用于显示和照明应用，能发出可见光。</p>',0,'',''),(395510,NULL,0,'',0,'','','',0,0,2000.000000,0,'',1500.000000,0,0,'','','','',2000.000000,2000.000000,0,'','','','','','','<p>用于计算机内存，提供快速的读写操作。</p>',0,'',''),(395511,NULL,0,'',0,'','','',0,0,2000.000000,0,'',1500.000000,0,0,'','','','',2000.000000,2000.000000,0,'','','','','','','<p>用于高功率应用，如电动汽车和工业电源中，用于开关高电流和高电压。</p>',0,'','');
