--
-- Table structure for table `ld_products_copy`
--

DROP TABLE IF EXISTS `ld_products_copy`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `ld_products_copy` (
  `productid` int(11) NOT NULL,
  `product_no` varchar(100) NOT NULL,
  `productname` text,
  `productcode` varchar(40) DEFAULT NULL,
  `productcategory` varchar(200) DEFAULT NULL,
  `manufacturer` varchar(200) DEFAULT NULL,
  `qty_per_unit` decimal(25,3) DEFAULT NULL,
  `unit_price` decimal(25,8) DEFAULT NULL,
  `weight` decimal(25,3) DEFAULT NULL,
  `pack_size` int(11) DEFAULT NULL,
  `sales_start_date` date DEFAULT NULL,
  `sales_end_date` date DEFAULT NULL,
  `start_date` date DEFAULT NULL,
  `expiry_date` date DEFAULT NULL,
  `cost_factor` int(11) DEFAULT NULL,
  `commissionrate` decimal(25,3) DEFAULT NULL,
  `commissionmethod` varchar(50) DEFAULT NULL,
  `discontinued` int(1) NOT NULL DEFAULT '0',
  `usageunit` varchar(200) DEFAULT NULL,
  `reorderlevel` int(11) DEFAULT NULL,
  `website` varchar(100) DEFAULT NULL,
  `taxclass` varchar(200) DEFAULT NULL,
  `mfr_part_no` varchar(200) DEFAULT NULL,
  `vendor_part_no` varchar(200) DEFAULT NULL,
  `serialno` varchar(200) DEFAULT NULL,
  `qtyinstock` decimal(25,8) DEFAULT NULL,
  `productsheet` text,
  `qtyindemand` int(11) DEFAULT NULL,
  `glacct` varchar(200) DEFAULT NULL,
  `vendor_id` int(11) DEFAULT NULL,
  `imagename` text,
  `currency_id` int(19) NOT NULL DEFAULT '1',
  `costprice` decimal(25,8) DEFAULT NULL,
  `qtyearly` decimal(25,8) DEFAULT NULL,
  `productgp` decimal(25,2) DEFAULT '0.00',
  `smownerid` int(11) DEFAULT '0',
  `smcreatorid` int(11) DEFAULT '0',
  `modifiedby` int(11) DEFAULT '0',
  `createdtime` datetime DEFAULT NULL,
  `modifiedtime` datetime DEFAULT NULL,
  `description` text,
  `deleted` int(11) DEFAULT '0',
  `approvestatus` varchar(200) DEFAULT '未提交',
  `approveby` int(1) DEFAULT NULL,
  `batchmanagement` int(1) DEFAULT '0',
  `regmaturitydate` date DEFAULT NULL,
  `currentapprover` varchar(1000) DEFAULT NULL,
  `print_times` int(11) DEFAULT '0',
  `approvetime` datetime DEFAULT NULL,
  `havepricestrategy` varchar(25) DEFAULT NULL,
  `productdate` date DEFAULT NULL,
  `protectqualitydate` date DEFAULT NULL,
  `made_in` varchar(100) DEFAULT NULL,
  `kis_id` int(22) DEFAULT '0',
  `kis_no` varchar(200) DEFAULT NULL,
  `advance_stage` varchar(100) DEFAULT NULL,
  `approvesubmitter` int(19) DEFAULT '0',
  `approvesubmittedtime` datetime DEFAULT NULL,
  `approveurgent` varchar(10) DEFAULT 'no',
  `approveexpediting` varchar(10) DEFAULT 'no',
  `currentapprovestepid` int(19) DEFAULT '0',
  `sign_longtitude` varchar(200) DEFAULT NULL,
  `sign_latitude` varchar(200) DEFAULT NULL,
  `sign_location_address` varchar(200) DEFAULT NULL,
  PRIMARY KEY (`productid`),
  KEY `product_no` (`product_no`),
  KEY `deleted` (`deleted`,`modifiedtime`) USING BTREE,
  CONSTRAINT `ld_products_copy_ibfk_1` FOREIGN KEY (`productid`) REFERENCES `ld_crmentity` (`crmid`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8;
/*!40101 SET character_set_client = @saved_cs_client */;

