DELIMITER ;;
/*!50003 CREATE*/ /*!50017 */ /*!50003 TRIGGER `yichong_reset_customform21info_quotes_before_edit` BEFORE UPDATE ON `ld_quotes` FOR EACH ROW BEGIN 

	IF @disable_triggers IS NULL THEN
		SET NEW.owner_role=(
			SELECT
				a.userlevel
			FROM ld_users a
			WHERE a.id=NEW.smownerid
		);

		
		
		
		

		SET @ycprice_quoteid=NEW.quoteid;
		SET NEW.price_info=(
				SELECT
					CASE
						WHEN MAX(price_info)=0 THEN '无需审批'
						WHEN MAX(price_info)=11 THEN '总经理审批'
						WHEN MAX(price_info)=21 THEN '总监审批'
						WHEN MAX(price_info)=22 THEN '总监审批+总经理审批'
						WHEN MAX(price_info)=31 THEN '经理审批'
						WHEN MAX(price_info)=32 THEN '经理审批+总监审批'
						WHEN MAX(price_info)=33 THEN '经理审批+总监审批+总经理审批'
						WHEN MAX(price_info)=34 THEN '经理审批+总监审批+总经理审批'
					END AS price_info
				FROM (
					SELECT 
						CASE
							WHEN IFNULL(u.userlevel,'') NOT IN ('部门经理','总监','总经理','副总经理') AND a.taxprice>=IFNULL(c.cf_3792,0)/IFNULL(b.sf7275,1)/IF(q.currency_id=7,1.13,1) THEN 0
							WHEN IFNULL(u.userlevel,'') NOT IN ('部门经理','总监','总经理','副总经理') AND a.taxprice<IFNULL(c.cf_3792,0)/IFNULL(b.sf7275,1)/IF(q.currency_id=7,1.13,1) AND a.taxprice>=IFNULL(c.cf_4012,0)/IFNULL(b.sf7275,1)/IF(q.currency_id=7,1.13,1) THEN 31
							WHEN IFNULL(u.userlevel,'') NOT IN ('部门经理','总监','总经理','副总经理') AND a.taxprice<IFNULL(c.cf_4012,0)/IFNULL(b.sf7275,1)/IF(q.currency_id=7,1.13,1) AND a.taxprice>=IFNULL(c.cf_4011,0)/IFNULL(b.sf7275,1)/IF(q.currency_id=7,1.13,1) THEN 32
							WHEN IFNULL(u.userlevel,'') NOT IN ('部门经理','总监','总经理','副总经理') AND a.taxprice<IFNULL(c.cf_4011,0)/IFNULL(b.sf7275,1)/IF(q.currency_id=7,1.13,1) THEN 33

							WHEN IFNULL(u.userlevel,'') IN ('部门经理') AND a.taxprice>=IFNULL(c.cf_4012,0)/IFNULL(b.sf7275,1)/IF(q.currency_id=7,1.13,1) THEN 0
							WHEN IFNULL(u.userlevel,'') IN ('部门经理') AND a.taxprice<IFNULL(c.cf_4012,0)/IFNULL(b.sf7275,1)/IF(q.currency_id=7,1.13,1) AND a.taxprice>=IFNULL(c.cf_4011,0)/IFNULL(b.sf7275,1)/IF(q.currency_id=7,1.13,1) THEN 21
							WHEN IFNULL(u.userlevel,'') IN ('部门经理') AND a.taxprice<IFNULL(c.cf_4011,0)/IFNULL(b.sf7275,1)/IF(q.currency_id=7,1.13,1) THEN 22

							WHEN IFNULL(u.userlevel,'') IN ('总监') AND a.taxprice>=IFNULL(c.cf_4011,0)/IFNULL(b.sf7275,1)/IF(q.currency_id=7,1.13,1) THEN 0
							WHEN IFNULL(u.userlevel,'') IN ('总监') AND a.taxprice<IFNULL(c.cf_4011,0)/IFNULL(b.sf7275,1)/IF(q.currency_id=7,1.13,1) THEN 11

							WHEN IFNULL(u.userlevel,'') IN ('总经理','副总经理') THEN 0
							ELSE 34
						END AS price_info
					FROM ld_quotesdetail a 
					LEFT JOIN ld_quotesdetailscf b ON a.lineitem_id=b.lineitem_id 
					LEFT JOIN ld_productcf c ON c.productid=a.productid 
					LEFT JOIN ld_quotes q ON a.id=q.quoteid
					LEFT JOIN ld_users u ON u.id=q.smownerid
				WHERE a.id=@ycprice_quoteid
				) a
			);

	
		IF NEW.approvestatus='审批中' AND NEW.price_info='无需审批' AND IFNULL((SELECT approveid FROM ld_approvelog WHERE crmid=@ycprice_quoteid ORDER BY id DESC LIMIT 1),0)=72 THEN
			SET NEW.approvestatus='已批准';
			SET NEW.currentapprover=NULL;
			SET NEW.approveby=NEW.approvesubmitter;
		END IF;
		
	END IF;

END */;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
