/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8 */ ;
/*!50003 SET character_set_results = utf8 */ ;
/*!50003 SET collation_connection  = utf8_general_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'NO_AUTO_CREATE_USER,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
/*!50003 CREATE*/ /*!50017 */ /*!50003 TRIGGER `yichong_reset_customform21info_quotes_edit` AFTER UPDATE ON `ld_quotes` FOR EACH ROW BEGIN 

	IF @disable_triggers IS NULL THEN
		SET @yc_quoteid=NEW.quoteid;
		SET @yccurrency_rate=IF(NEW.currency_id=1,1,1.13);
		
		
		
		
		UPDATE ld_quotesdetail a
		LEFT JOIN ld_quotesdetailscf b ON b.lineitem_id=a.lineitem_id
		LEFT JOIN ld_productcf c ON c.productid=a.productid  
		SET b.sf10811=IFNULL(c.cf_3792,0)/IFNULL(b.sf7275,1)/@yccurrency_rate,
				b.sf10947=IFNULL(c.cf_4012,0)/IFNULL(b.sf7275,1)/@yccurrency_rate,
				b.sf11083=IFNULL(c.cf_4011,0)/IFNULL(b.sf7275,1)/@yccurrency_rate,
				b.sf9315=IFNULL(c.cf_3930,0)/IFNULL(b.sf7275,1)/@yccurrency_rate,
				b.sf9043=100*(a.taxprice-IFNULL(c.cf_3930,0)/IFNULL(b.sf7275,1)/@yccurrency_rate)/a.taxprice
		WHERE a.id=@yc_quoteid;
		
		SET @yc_baojia_info=(
			SELECT
			CONCAT('<table border="1" cellpadding="0" cellspacing="0" style="width:100%; margin-top:2mm; line-height:7mm">',
				'<tr>',
					'<td style="padding-left:1mm">产品名称</td>',
					'<td style="padding-left:1mm">币别</td>',
					'<td style="padding-left:1mm">增值税</td>',
					'<td align="right" style="padding-right:1mm">报价汇率</td>',
					'<td align="right" style="padding-right:1mm">交易单价</td>',
					'<td align="right" style="padding-right:1mm">代理商单价</td>',
					'<td align="right" style="padding-right:1mm">代理商利润%</td>',
					'<td align="right" style="padding-right:1mm">代工厂单价</td>',
					'<td align="right" style="padding-right:1mm">代工厂利润%</td>',
					'<td align="right" style="padding-right:1mm">品牌单价</td>',
				'</tr>',
				(
					SELECT
							GROUP_CONCAT(CONCAT('<tr>',
								'<td style="padding-left:1mm">',IFNULL(productname,'&nbsp;'),'</td>',
								'<td style="padding-left:1mm">',IFNULL(bizhong,'&nbsp;'),'</td>',
								'<td align="right" style="padding-right:1mm">',IFNULL(taxadd,'&nbsp;'),'</td>',
								'<td align="right" style="padding-right:1mm">',IFNULL(huilv,'&nbsp;'),'</td>',
								'<td align="right" style="padding-right:1mm">',IFNULL(taxprice,'&nbsp;'),'</td>',
								'<td align="right" style="padding-right:1mm">',IFNULL(dailiprice,'&nbsp;'),'</td>',
								'<td align="right" style="padding-right:1mm">',IFNULL(lirun_dl,'0'),'</td>',
								'<td align="right" style="padding-right:1mm">',IFNULL(daigongprice,'&nbsp;'),'</td>',
								'<td align="right" style="padding-right:1mm">',IFNULL(lirun_dg,'0'),'</td>',													
								'<td align="right" style="padding-right:1mm">',IFNULL(pinpaiprice,'&nbsp;'),'</td>'	
							)  SEPARATOR '
						') AS mydata
						FROM (
							SELECT
								c.productname,
								c.product_no,
								c.productsheet,
								CASE
									WHEN q.currency_id=1 THEN '人民币'
									WHEN q.currency_id=6 THEN '欧元'
									WHEN q.currency_id=7 THEN '美元'
									WHEN q.currency_id=8 THEN '英镑'
									WHEN q.currency_id=9 THEN '日元'
									ELSE q.currency_symbol
								END AS bizhong,
								ROUND(b.sf7275,6) AS huilv,
								ROUND(a.tax_added,2) AS taxadd,
								FORMAT(a.taxprice,6) AS taxprice,
								FORMAT(b.sf8363,6) AS dailiprice,

								CONCAT(FORMAT((b.sf7411-b.sf8363)*100/b.sf7411,2),'%') AS lirun_dl,
								FORMAT(b.sf7411,6) AS daigongprice,
								CONCAT(FORMAT((b.sf7547-b.sf7411)*100/b.sf7547,2),'%') AS lirun_dg,
								FORMAT(b.sf7547,6) AS pinpaiprice
							FROM ld_quotes q
							LEFT JOIN ld_quotesdetail a ON a.id=q.quoteid
							LEFT JOIN ld_quotesdetailscf b ON b.lineitem_id=a.lineitem_id
							LEFT JOIN ld_products c ON c.productid=a.productid
							WHERE a.id=@yc_quoteid
								AND b.sf12035='Y'
						) t
				),
				'</table>'
			) AS mydata
		);
		
		SELECT 
			IFNULL(u.last_name,''),
			IFNULL(b.cf_3381,''),
			IFNULL(b.cf_3382,''),
			IFNULL((SELECT currency_code FROM ld_currency_info WHERE id=a.currency_id AND deleted=0 LIMIT 1),'') AS currency_code
		INTO 
			@yc_baojia_owner,
			@yc_baojia_date,
			@yc_baojia_tilldate,
			@yc_baojia_bizhong
		FROM ld_quotes a
		LEFT JOIN ld_quotescf b ON b.quoteid=a.quoteid
		LEFT JOIN ld_users u ON u.id=a.smownerid
		WHERE a.quoteid=@yc_quoteid;

		UPDATE ld_customform21 SET 
			baojia_date=@yc_baojia_date,
			baojia_tilldate=@yc_baojia_tilldate,
			baojia_owner=@yc_baojia_owner,
			baojia_info=@yc_baojia_info,
			baojia_bizhong=@yc_baojia_bizhong,
			quote_lirun_dg='abcdefg',
			modifiedtime=NEW.modifiedtime
		WHERE quote_id=@yc_quoteid;
	END IF;

END */;;
DELIMITER ;
