ght:1mm\">\',IFNULL(lirun_dg,\'0\'),\'</td>\',													\r\n					\'<td align=\"right\" style=\"padding-right:1mm\">\',IFNULL(pinpaiprice,\'&nbsp;\'),\'</td>\'	\r\n				)  SEPARATOR \'\r\n			\') AS mydata\r\n			FROM (\r\n				SELECT\r\n					c.productname,\r\n					c.product_no,\r\n					c.productsheet,\r\n					CASE\r\n						WHEN q.currency_id=1 THEN \'人民币\'\r\n						WHEN q.currency_id=6 THEN \'欧元\'\r\n						WHEN q.currency_id=7 THEN \'美元\'\r\n						WHEN q.currency_id=8 THEN \'英镑\'\r\n						WHEN q.currency_id=9 THEN \'日元\'\r\n						ELSE q.currency_symbol\r\n					END AS bizhong,\r\n					ROUND(b.sf7275,6) AS huilv,\r\n					ROUND(a.tax_added,2) AS taxadd,\r\n					FORMAT(a.taxprice,6) AS taxprice,\r\n					FORMAT(b.sf8363,6) AS dailiprice,\r\n\r\n					CONCAT(FORMAT((b.sf7411-b.sf8363)*100/b.sf7411,2),\'%\') AS lirun_dl,\r\n					FORMAT(b.sf7411,6) AS daigongprice,\r\n					CONCAT(FORMAT((b.sf7547-b.sf7411)*100/b.sf7547,2),\'%\') AS lirun_dg,\r\n					FORMAT(b.sf7547,6) AS pinpaiprice\r\n				FROM ld_quotes q\r\n				LEFT JOIN ld_quotesdetail a ON a.id=q.quoteid\r\n				LEFT JOIN ld_quotesdetailscf b ON b.lineitem_id=a.lineitem_id\r\n				LEFT JOIN ld_products c ON c.productid=a.productid\r\n				WHERE a.id=?\r\n					AND b.sf12035=\'Y\' \r\n			) t\r\n	),\r\n	\'</table>\'\r\n) AS mydata',NULL,NULL),(472,NULL,'main','',3931,4024,NULL,'sql','SELECT b.last_name FROM ld_quotes a LEFT JOIN ld_users b ON b.id=a.smownerid WHERE a.quoteid=?',NULL,NULL),(473,NULL,'main','',3121,3931,NULL,'sql','SELECT\r\n	ld_quotes.quoteid,ld_quotes.quote_no\r\nFROM ld_quotes\r\nWHERE deleted=0\r\n	AND approvestatus=\'已批准\'\r\n	AND potentialid=(SELECT potentialid FROM ld_customform22 WHERE customform22id=?)\r\nORDER BY createdtime DESC LIMIT 1',NULL,NULL),(474,NULL,'main','',3121,3534,'','column','accountid','',NULL),(475,NULL,'main',NULL,3427,4041,'cf_4041','column','cf_4039','Potentials',NULL),(476,NULL,'main',NULL,3121,4042,'cf_4042','column','cf_4041','CustomForm22',NULL),(477,NULL,'main',NULL,316,4049,'c