/*!50003 CREATE*/ /*!50017 */ /*!50003 TRIGGER `update_by_salesorder1` BEFORE UPDATE ON `ld_salesorder` FOR EACH ROW BEGIN 

IF @disable_triggers IS NULL THEN
	IF NEW.triggercount<>OLD.triggercount THEN
		SET NEW.receivable_balance=ROUND(IFNULL(NEW.total,0)-IFNULL(NEW.received_amount,0),2);
		SET NEW.total_rmb=IFNULL((
			SELECT
				SUM(b.sf7003)
			FROM ld_salesorderdetail a
			LEFT JOIN ld_salesorderdetailscf b ON b.lineitem_id=a.lineitem_id
			WHERE a.id=NEW.salesorderid
			),0);
	END IF;

	IF NEW.currency_id=1 THEN
		SET NEW.conversion_rate_bill=1;
		SET NEW.conversion_rate=1;
	ELSE
		SET NEW.conversion_rate=(SELECT b.sf14274 FROM ld_salesorderdetail a LEFT JOIN ld_salesorderdetailscf b ON a.lineitem_id=b.lineitem_id WHERE a.id=NEW.salesorderid LIMIT 1);
		SET NEW.conversion_rate_bill=(SELECT b.sf7275 FROM ld_salesorderdetail a LEFT JOIN ld_salesorderdetailscf b ON a.lineitem_id=b.lineitem_id WHERE a.id=NEW.salesorderid LIMIT 1);
	END IF;
END IF;

END */;;
