			SELECT
				SUM(b.sf15246)
			FROM ld_servicecontractsdetail a
			LEFT JOIN ld_servicecontractsdetailscf b ON b.lineitem_id=a.lineitem_id
			WHERE a.id=NEW.servicecontractsid
			),0);
	END IF;

END */;;
