INSERT INTO `ld_troubletickets` VALUES (395963,'TT100001',NULL,NULL,NULL,NULL,'',NULL,NULL,NULL,'',NULL,NULL,NULL,NULL,'电话',NULL,NULL,NULL,'未提交',0,395408,0,NULL,NULL,31,1,1,'2024-08-16 00:05:18','2024-08-16 00:05:18',0,'华为手机充电断充',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,NULL,0,NULL,NULL,'',NULL,0,NULL,NULL,NULL,'',0,0,NULL,'安世半导体（中国）有限公司',0,NULL,'no','no',0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),(395964,'TT100002',NULL,NULL,NULL,NULL,'',NULL,NULL,NULL,'',NULL,NULL,NULL,NULL,'远程',NULL,NULL,NULL,'未提交',0,395406,0,NULL,NULL,5,1,1,'2024-08-16 00:05:19','2024-08-16 00:05:19',0,'CPS1001烧Boot后无法正常连接，王工已解决问题。',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,NULL,0,NULL,NULL,'',NULL,0,NULL,NULL,NULL,'',0,0,NULL,'日月新半导体（昆山）有限公司',0,NULL,'no','no',0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),(395965,'TT100003',NULL,NULL,NULL,NULL,'',NULL,NULL,NULL,'',NULL,NULL,NULL,NULL,'远程',NULL,NULL,NULL,'未提交',0,395404,0,NULL,NULL,31,1,1,'2024-08-16 00:05:19','2024-08-16 00:05:19',0,'DC12V输入，无线充不支持15W输出，只有10W，需要提供一版软件能支持15W输出',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,NULL,0,NULL,NULL,'',NULL,0,NULL,NULL,NULL,'',0,0,NULL,'海太半导体（无锡）有限公司',0,NULL,'no','no',0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),(395966,'TT100004',NULL,NULL,NULL,NULL,'',NULL,NULL,NULL,'',NULL,NULL,NULL,NULL,'送修',NULL,NULL,NULL,'未提交',0,395402,0,NULL,NULL,32,1,1,'2024-08-16 00:05:19','2024-08-16 00:05:19',0,'板子不工作 刘工已解决问题',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,NULL,0,NULL,NULL,'',NULL,0,NULL,NULL,NULL,'',0,0,NULL,'盛合晶微半导体（江阴）有限公司',0,NULL,'no','no',0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),(395967,'TT100005',NULL,NULL,NULL,NULL,'',NULL,NULL,NULL,'',NULL,NULL,NULL,NULL,'上门',NULL,NULL,NULL,'未提交',0,395400,0,NULL,NULL,5,1,1,'2024-08-16 00:05:19','2024-08-16 00:05:19',0,'板子无法升级，王工已过来处理完成',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,NULL,0,NULL,NULL,'',NULL,0,NULL,NULL,NULL,'',0,0,NULL,'深圳市金誉半导体股份有限公司',0,NULL,'no','no',0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),(395968,'TT100006',NULL,NULL,NULL,NULL,'',NULL,NULL,NULL,'',NULL,NULL,NULL,NULL,'送修',NULL,NULL,NULL,'未提交',0,395398,0,NULL,NULL,31,1,1,'2024-08-16 00:05:19','2024-08-16 00:05:19',0,'1、FOD 检测，检测5毛钱硬币和30mm 铁片 不是强制项，能过EPP 即可，但是3mm 偏移10mm ，能充电.一定要确保.\n2、还有手机兼容性，现在部分苹果手机测到进不去快充的，手机吹凉了还是进不去，换其他产品测试能进入快充\nUI测试					\n序号	使用对象	问题点		测试结果	备注\n1	        作为用户	我的手机非无线充电手机，放上去会怎样？		会报警LED闪烁	\n2		放了一个小金属物件上去，会怎样？		产品无反应，处于待机状态，无报警	\n3		我把手机放反了，我的是充电手机，会怎样？		手机不充电产品会报警LED闪烁	\n4		我有充电手机，没有竖（横）放在中心，会怎样	1、会不会出现 FOD死角区域	手机放在线圈接收范围边缘时产品会报警手机不充电	\n	        2、太偏：会不会充入温度保护：保护时LED状态	手机放在线圈接收范围边缘时产品会报警手机不充电	\n5		手机正用有线充电再把手机放到无线充上，会怎样？ 把顺序反过来，会怎样？		手机正用有线充电再把手机放到无线充上还是显示有线充电，拔  \n                掉充电线后手机会转为无线充电，把顺序反过来时手机会从无线充电转为有线充电	\n6		我的手机壳后有个5角硬币，放到无线充上，会怎样？		手机会正常充电，产品不会报警	\n7		正在充电的手机，我打游戏或滑动屏幕，会有影响吗？		无影响	\n8		无线充手机关机，完全没电，放到无线充上，会充电正常吗？		充电正常	\n9		我边充电边看电影，会怎样？		无影响	\n10		手机先放在无线充上，并接上220V充电		充电正常	\n11		充电时，有电话进入（手机震动），接到/没接到会怎样？		手机正常充电	\n12		220V插头接触不良，无线充正在充电，会怎样？		无线会断开充电	\n13		在用的时候会不会有很烦人的东西存在？比如说灯太亮？太暗？声音太大？		没有	\n14		没有用过无线充，我能只通过看产品本身然后知道线圈的位置吗？		可以通过上盖看到线圈	\n15		我把产品供电用电脑USB供电然后给手机充电，产品会怎样？		会有5V供电给产品能给手机正常充电',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,NULL,0,NULL,NULL,'',NULL,0,NULL,NULL,NULL,'',0,0,NULL,'重庆超硅半导体有限公司',0,NULL,'no','no',0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),(395969,'TT100007',NULL,NULL,NULL,NULL,'',NULL,NULL,NULL,'',NULL,NULL,NULL,NULL,'送修',NULL,NULL,NULL,'未提交',0,395396,0,NULL,NULL,31,1,1,'2024-08-16 00:05:19','2024-08-16 00:05:19',0,'客户收到样品反馈的问题：\n1：12V供电时，任意一款手机FOD报警之后大概率放其他手机上去充会直接闪灯报警，无法充电，需重新上电\n2：12V供电时，无法给谷歌系列手机充电，放上去会直接闪灯报警\n3：12V供电时，垫高5MM，放上三星NOTE10充电会触发FOD报警，并且手机拿开后灯闪不停，只能重新上电，要求垫高5MM能正常充电不报警\n4：5V供电时，垫高6.5MM，放上三星NOTE10充电会触发FOD报警，并且手机拿开后灯闪不停，只能重新上电，要求手机拿开后FOD闪灯能正常熄灭\n5：5V供电时，Iphone背上异物测试FOD之后拿开手机，有概率会导致系统挂掉，此时手机直接放中心充电会完全没任何反应，只能重新上电\n6：5V供电时，三星背上异物测试FOD之后再取掉异物重新放置手机也会闪灯报警，只能重新上电\n7:上电灯亮2S后就熄灭进入待机状态。要求3S左右才熄灭。',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,NULL,0,NULL,NULL,'',NULL,0,NULL,NULL,NULL,'',0,0,NULL,'江苏时代芯存半导体有限公司',0,NULL,'no','no',0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),(395970,'TT100008',NULL,NULL,NULL,NULL,'',NULL,NULL,NULL,'',NULL,NULL,NULL,NULL,'其他',NULL,NULL,NULL,'未提交',0,395394,0,NULL,NULL,36,1,1,'2024-08-16 00:05:19','2024-08-16 00:05:19',0,'客户选用8014A做EPP15W无线充，已经做出原理图，请帮忙审核是否有问题，客户好开始layout',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,NULL,0,NULL,NULL,'',NULL,0,NULL,NULL,NULL,'',0,0,NULL,'广东芯聚能半导体有限公司',0,NULL,'no','no',0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),(395971,'TT100009',NULL,NULL,NULL,NULL,'',NULL,NULL,NULL,'',NULL,NULL,NULL,NULL,'远程',NULL,NULL,NULL,'未提交',0,395392,0,NULL,NULL,5,1,1,'2024-08-16 00:05:19','2024-08-16 00:05:19',0,'5V1A及以下功率输入的情况，根据是否触发DPL，来输出相应状态。如触发DPL，则关闭功率传输，给用户灯光提示(具体如何提示会以邮件再输出给CPS)；如不触发，则按照正常状态充电；\n    ——灯光提示需求如下：\n    1). 充电 - 绿灯常亮\n    2). 充满/没充电 - 不亮灯\n    3). 充电异常 - 灯闪15秒后灭灯（快闪亮300ms，灭300ms, 循环)。这个异常指触发DPL异常，其余FOD之类的异常按旧需求不指示\n请帮忙修改，~软件更新后，请安排5PCS样品给亿联确认。谢谢~',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,NULL,0,NULL,NULL,'',NULL,0,NULL,NULL,NULL,'',0,0,NULL,'深圳市微源半导体股份有限公司',0,NULL,'no','no',0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),(395972,'TT100010',NULL,NULL,NULL,NULL,'',NULL,NULL,NULL,'',NULL,NULL,NULL,NULL,'其他',NULL,NULL,NULL,'未提交',0,395390,0,NULL,NULL,36,1,1,'2024-08-16 00:05:19','2024-08-16 00:05:19',0,'请帮忙审核客户画的8013A的原理图，做变频EPP-15W',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,NULL,0,NULL,NULL,'',NULL,0,NULL,NULL,NULL,'',0,0,NULL,'江西兆驰半导体有限公司',0,NULL,'no','no',0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),(395973,'TT100011',NULL,NULL,NULL,NULL,'',NULL,NULL,NULL,'',NULL,NULL,NULL,NULL,'远程',NULL,NULL,NULL,'未提交',0,395388,0,NULL,NULL,31,1,1,'2024-08-16 00:05:19','2024-08-16 00:05:19',0,'我们4029接收项目，因客人现在的发射板主要是旧的PPDE协义的。所以需要提供一个BPP+旧的PPDE协议的接收软件，以满足客人的需求。麻烦改一个旧的PPDE的协议的接收软件。谢谢。',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,NULL,0,NULL,NULL,'',NULL,0,NULL,NULL,NULL,'',0,0,NULL,'深圳市威兆半导体股份有限公司',0,NULL,'no','no',0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),(395974,'TT100012',NULL,NULL,NULL,NULL,'',NULL,NULL,NULL,'',NULL,NULL,NULL,NULL,'上门',NULL,NULL,NULL,'未提交',0,395383,0,NULL,NULL,31,1,1,'2024-08-16 00:05:19','2024-08-16 00:05:19',0,'客人需要配BPP+私有协议快充发射盘。需要提供匹配这个协议的接收软件。',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,NULL,0,NULL,NULL,'',NULL,0,NULL,NULL,NULL,'',0,0,NULL,'中微半导体设备（上海）股份有限公司',0,NULL,'no','no',0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),(395975,'TT100013',NULL,NULL,NULL,NULL,'',NULL,NULL,NULL,'',NULL,NULL,NULL,NULL,'其他',NULL,NULL,NULL,'未提交',0,395385,0,NULL,NULL,31,1,1,'2024-08-16 00:05:19','2024-08-16 00:05:19',0,'胡经理：\n我司现有接收器项目，平台为CPS4029。软件有如下需求：\n\n1，只允许输出5V，所以需要一个只支持5W的接收软件，不能在   5W以上的发射板上有输出9V  12V的现象，不然会烧后端电路元件\n\n2，同以上，只需要9V，所以需要一个只支持10W的接收软件。\n\n3，兼容5W   10W  15W的通用软件\n\n以上请最好能8月4号给到我司，以便我司能顺利出样客户。\n\n不胜感谢！',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,NULL,0,NULL,NULL,'',NULL,0,NULL,NULL,NULL,'',0,0,NULL,'比亚迪半导体股份有限公司',0,NULL,'no','no',0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),(395976,'TT100014',NULL,NULL,NULL,NULL,'',NULL,NULL,NULL,'',NULL,NULL,NULL,NULL,'其他',NULL,NULL,NULL,'未提交',0,395381,0,NULL,NULL,35,1,1,'2024-08-16 00:05:19','2024-08-16 00:05:19',0,'定频双线圈EC8024A的方案无法正常工作。请易冲的软件工程师协助看看',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,NULL,0,NULL,NULL,'',NULL,0,NULL,NULL,NULL,'',0,0,NULL,'上海积塔半导体有限公司',0,NULL,'no','no',0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),(395977,'TT100015',NULL,NULL,NULL,NULL,'',NULL,NULL,NULL,'',NULL,NULL,NULL,NULL,'远程',NULL,NULL,NULL,'未提交',0,395379,0,NULL,NULL,32,1,1,'2024-08-16 00:05:19','2024-08-16 00:05:19',0,'客户针对15W无线充的灯效和充电功率有要求，需要易冲的软件及硬件工程师配合',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,NULL,0,NULL,NULL,'',NULL,0,NULL,NULL,NULL,'',0,0,NULL,'苏州晶方半导体科技股份有限公司',0,NULL,'no','no',0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),(395978,'TT100016',NULL,NULL,NULL,NULL,'',NULL,NULL,NULL,'',NULL,NULL,NULL,NULL,'其他',NUL