  `success_time` datetime NOT NULL COMMENT '支付完成时间 ',
  `payer_openid` varchar(128) NOT NULL COMMENT '支付者信息,用户在直连商户appid下的唯一标识。 ',
  `payer_total` decimal(15,2) NOT NULL COMMENT '支付金额',
