	SET in_str=REPLACE(in_str,'ｍ','m');
	SET in_str=REPLACE(in_str,'ｎ','n');

	SET in_str=REPLACE(in_str,'ｏ','o');
	SET in_str=REPLACE(in_str,'ｐ','p');
