		set @TMPSQL_THREE=concat('insert into ld_logpublicaccount(username,operation,opdate,accountid,pool_id,old_smownerid,programmeid) ',@TMPSQL_LOG_TWO);

prepare stmt from @TMPSQL_THREE;
