/*!50003 DROP PROCEDURE IF EXISTS `addmodule_stuff_salesrangking` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8 */ ;
/*!50003 SET character_set_results = utf8 */ ;
/*!50003 SET collation_connection  = utf8_general_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'NO_AUTO_CREATE_USER,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE  PROCEDURE `addmodule_stuff_salesrangking`()
begin
IF NOT  EXISTS(select * from ld_stuff where `stufftitle` = 'SALESCHARTS' AND FIND_IN_SET('Invoice',datarangmodule)) then
UPDATE ld_stuff SET relatedmodule = CONCAT(relatedmodule,',Invoice,OutboundOrder'),datarangmodule = CONCAT(datarangmodule,',Invoice,OutboundOrder') WHERE `stufftitle` = 'SALESCHARTS';

INSERT INTO ld_homestuffdetail(stuffid,stufflabel,stufflabeltype,compute_columns,compute_type,stufflabel_zh,stufflabel_en,daterange,viewrange,is_default,compute_module,advance_demand,advance_demand_groups,topnumber)
SELECT 33,'SalesRanking_Invoice','fixedstr','ld_invoice.total','sum','开票金额','Invoice Amount','','ld_invoice:smownerid:assigned_user_id:Invoice_fieldlabel:V','yes','Invoice','','',0
FROM DUAL WHERE NOT EXISTS(SELECT 1 FROM ld_homestuffdetail WHERE stufflabel='SalesRanking_Invoice' and compute_module='Invoice' and stuffid=33);

INSERT INTO ld_homestuffdetail(stuffid,stufflabel,stufflabeltype,compute_columns,compute_type,stufflabel_zh,stufflabel_en,daterange,viewrange,is_default,compute_module,advance_demand,advance_demand_groups,topnumber)
SELECT 33,'SalesRanking_OutboundOrder','fixedstr','ld_outboundorder.total','sum','出库金额','OutboundOrder Amount','','ld_outboundorder:smownerid:assigned_user_id:OutboundOrder_fieldlabel:V','yes','OutboundOrder','','',0
FROM DUAL WHERE NOT EXISTS(SELECT 1 FROM ld_homestuffdetail WHERE stufflabel='SalesRanking_OutboundOrder' and compute_module='OutboundOrder' and stuffid=33);
end if ;
end ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
