	tmp_sendtime DATETIME,
	tmp_sender VARCHAR(100),
	tmp_relatedid INT(19)
)
BEGIN

	SET @cnt=(SELECT COUNT(SubmitTime) FROM ld_smssend WHERE DATE_FORMAT(SubmitTime,'%Y-%m-%d')=CURDATE());

	INSERT INTO ld_smssend(
		TaskID,
		BatchNo,
		CalledNumber,
		SmsContent,
		SubmitTime,
		CreateTime,
		SmsResult,
		SmsBillingFee,
		operator,
		ReceiveContacts,
		FDataStatu,
		relatieid
	)
	SELECT
		IFNULL((SELECT MAX(TaskID) FROM ld_smssend),0)+1,
		CONCAT('sms',DATE_FORMAT(NOW(),'%Y%m%d'),LPAD(@cnt+1,8,0)),
		tmp_mobile,
		tmp_content,
		tmp_sendtime,
		NOW(),
		0,
		0.00,
		tmp_sender,
		tmp_jieshouren,
		0,
		tmp_relatedid;

end ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `ldcrm_defaultcreateprofileon` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8 */ ;
/*!50003 SET character_set_results = utf8 */ ;
/*!50003 SET collation_connection  = utf8_general_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'NO_AUTO_CREATE_USER,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE  PROCEDURE `ldcrm_defaultcreateprofileon`(
    modulename varchar(50),
    permissions int(19)
)
begin
	declare done int default 0;
	declare pprofileid  int ;
	declare cur1 CURSOR FOR SELECT profileid FROM ld_profile where profileid!=1;
declare continue handler  for not   found  SET done =1;
	set @sql = concat('select tabid into @tabid from ld_tab where name=','''',modulename,'''');
prepare stmt from @sql;
execute stmt;
deallocate  prepare stmt;
OPEN cur1;
Fetch cur1 into pprofileid;
loop1: while  done<>1 DO
	set @sql=CONCAT('insert into ld_profile2standardpermissions(profileid,tabid,operation,permissions) select  ' ,pprofileid,',',@tabid,',',4,',',permissions,'  from dual  where not exists (select 1 from ld_profile2standardpermissions where profileid=',pprofileid, ' and  tabid=',@tabid,' and operation=4)' );
prepare stmt from @sql;
execute stmt;
deallocate prepare stmt;
set @sql=CONCAT('insert into ld_profile2standardpermissions(profileid,tabid,operation,permissions) select  ' ,pprofileid,',',@tabid,',',11,',',permissions,'  from dual  where not exists (select 1 from ld_profile2standardpermissions where profileid=',pprofileid, ' and  tabid=',@tabid,' and operation=11)' );
prepare stmt from @sql;
execute stmt;
deallocate prepare stmt;
Fetch cur1 into pprofileid;
end while loop1;
close cur1;
end ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `ldcrm_read_tmpreminder` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8 */ ;
/*!50003 SET character_set_results = utf8 */ ;
/*!50003 SET collation_connection  = utf8_general_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'NO_AUTO_CREATE_USER,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE  PROCEDURE `ldcrm_read_tmpreminder`(
)
BEGIN
	DECLARE tmp_id INT(19) DEFAULT 0;
	DECLARE tmp_content text DEFAULT '';
	DECLARE tmp_recieverid INT(19) DEFAULT 0;
	DECLARE tmp_remindtime datetime;
	DECLARE tmp_reltab varchar(100) DEFAULT '';
	DECLARE tmp_related_to INT(19) DEFAULT 0;
	DECLARE tmp_ruleid INT(19) DEFAULT 0;

	DECLARE Mycur CURSOR FOR 
		SELECT
			id,
			content,
			reminderid,
			remindtime,
			reltab,
			related_to,
			reminds_ruleid 
		FROM ld_tmpreminder 
		WHERE remindtime<=NOW() 
			AND IFNULL(content,'') not like '%[var.%'
		ORDER BY remindtime DESC LIMIT 50;

	DECLARE CONTINUE HANDLER FOR SQLSTATE '02000' set tmp_id = NULL;

	OPEN Mycur;
	FETCH Mycur INTO tmp_id,tmp_content,tmp_recieverid,tmp_remindtime,tmp_reltab,tmp_related_to,tmp_ruleid;
	WHILE (tmp_id IS NOT NULL) DO
		DELETE FROM ld_tmpreminder WHERE id=tmp_id;
		set @maxid=0;
		select max(crmid) into @maxid from ld_crmentity;
		insert into ld_crmentity(crmid,setype)
		select @maxid+1,'Reminds';
		
		update ld_crmentity_seq set id=(select max(crmid) from ld_crmentity);
			
		insert into ld_reminds(remindsid,content,date_time,recieverid,status_rmd,related_to,reltab,is_del_send,is_del_rec,reminds_ruleid,smownerid,smcreatorid,modifiedby,createdtime,modifiedtime,description,deleted)
		select @maxid+1,tmp_content,tmp_remindtime,tmp_recieverid,'未读',tmp_related_to,tmp_reltab,0,0,tmp_ruleid,0,0,0,tmp_remindtime,tmp_remindtime,null,0
		from dual where not exists (select 1 from ld_reminds where content=tmp_content AND recieverid=tmp_recieverid and related_to=tmp_related_to and date_time=tmp_remindtime and reminds_ruleid=tmp_ruleid);

	FETCH Mycur INTO tmp_id,tmp_content,tmp_recieverid,tmp_remindtime,tmp_reltab,tmp_related_to,tmp_ruleid;
	END WHILE;
	CLOSE Mycur;	
	
end ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `ldcrm_refresh_advance_stage` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8 */ ;
/*!50003 SET character_set_results = utf8 */ ;
/*!50003 SET collation_connection  = utf8_general_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'NO_AUTO_CREATE_USER,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE  PROCEDURE `ldcrm_refresh_advance_stage`()
BEGIN

	DECLARE tmp_tablename varchar(50) DEFAULT '';
	DECLARE tmp_fieldname varchar(100) DEFAULT '';
	DECLARE tmp_dir_tablename varchar(50) DEFAULT '';
	DECLARE tmp_entityidfield varchar(150) DEFAULT '';

	DECLARE MYCUSOR CURSOR FOR
        SELECT
            (SELECT tablename FROM ld_field a WHERE tabid=ld_settings_advance.tabid AND columnname='createdtime') AS `tablename`,
            ld_field.`columnname` ,
            ld_field.`tablename` as `dir_tablename`,
            ld_entityname.entityidfield
        FROM ld_settings_advance
        LEFT JOIN ld_field ON ld_field.tabid = ld_settings_advance.tabid AND ld_field.fieldname = ld_settings_advance.module_field
        LEFT JOIN ld_entityname on ld_entityname.tabid = ld_settings_advance.tabid
        WHERE (`enable` = 'yes' or `showadvancemobile` = 'yes');
    DECLARE CONTINUE HANDLER FOR SQLSTATE '02000' SET tmp_tablename = NULL,tmp_fieldname = NULL;

	set @disable_triggers = 'ldcrm_refresh_advance_stage';

    OPEN MYCUSOR;
    FETCH MYCUSOR INTO tmp_dir_tablename,tmp_fieldname,tmp_tablename,tmp_entityidfield;
    WHILE(tmp_tablename IS NOT NULL) DO
    
        SET @update_sql = (
                    CASE
                        WHEN tmp_tablename = tmp_dir_tablename THEN CONCAT("UPDATE ",tmp_dir_tablename," SET advance_stage = ",tmp_fieldname," WHERE deleted=0 AND advance_stage <> ",tmp_fieldname,";")
                        ELSE CONCAT("UPDATE ",tmp_dir_tablename," LEFT JOIN ",tmp_tablename," ON ",tmp_tablename,".",tmp_entityidfield," = ",tmp_dir_tablename,".",tmp_entityidfield," SET advance_stage = ",tmp_fieldname," WHERE deleted=0 AND advance_stage <> ",tmp_fieldname,";")
                    END
                );
        SET @update_sql=REPLACE(@update_sql,'ld_faqscf.id', 'ld_faqscf.faqid');
        
        PREPARE stmtt FROM @update_sql;
        EXECUTE stmtt;
        DEALLOCATE PREPARE stmtt;

        FETCH MYCUSOR INTO tmp_dir_tablename,tmp_fieldname,tmp_tablename,tmp_entityidfield;
    END WHILE;
    CLOSE MYCUSOR;

    set @disable_triggers = NULL;

END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `ldcrm_remindsdata_delete` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8 */ ;
/*!50003 SET character_set_results = utf8 */ ;
/*!50003 SET collation_connection  = utf8_general_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'NO_AUTO_CREATE_USER,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE  PROCEDURE `ldcrm_remindsdata_delete`(
)
BEGIN

	DECLARE tmp_deldataids MEDIUMTEXT DEFAULT NULL;

	
	DECLARE REMIND_DELCUSOR CURSOR FOR 
		SELECT
			GROUP_CONCAT(remindsid) AS ids
		FROM (
			SELECT 
				remindsid
			FROM ld_reminds_accepted 
			WHERE date_time<DATE_SUB(CURDATE(),INTERVAL 3 MONTH)
			LIMIT 200
		) a;

	DECLARE CONTINUE HANDLER FOR SQLSTATE '02000' SET tmp_deldataids = NULL;

	OPEN REMIND_DELCUSOR; 
	FETCH REMIND_DELCUSOR INTO tmp_deldataids;
	WHILE(tmp_deldataids IS NOT NULL) DO
		DELETE FROM ld_reminds_accepted WHERE FIND_IN_SET(remindsid,tmp_deldataids);
		DELETE FROM ld_crmentity WHERE setype='Reminds' AND FIND_IN_SET(crmid,tmp_deldataids);
		FETCH REMIND_DELCUSOR INTO tmp_deldataids;
	END WHILE;
	CLOSE REMIND_DELCUSOR;

END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `ldcrm_remindsdata_transfer` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8 */ ;
/*!50003 SET character_set_results = utf8 */ ;
/*!50003 SET collation_connection  = utf8_general_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'NO_AUTO_CREATE_USER,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE  PROCEDURE `ldcrm_remindsdata_transfer`(
)
BEGIN

	DECLARE tmp_dataids MEDIUMTEXT DEFAULT NULL;

	
	DECLARE REMIND_CUSOR CURSOR FOR 
		SELECT
			GROUP_CONCAT(remindsid) AS ids
		FROM (
			SELECT 
				remindsid
			FROM ld_reminds 
			WHERE date_time<DATE_SUB(CURDATE(),INTERVAL 1 MONTH)
				AND (
					status_rmd='已读' 
					OR push_to_yzj=3
					OR push_to_weixin=3 
					OR push_to_ding=3
			)
			LIMIT 1000
		) a;

	DECLARE CONTINUE HANDLER FOR SQLSTATE '02000' SET tmp_dataids = NULL;

	OPEN REMIND_CUSOR; 
	FETCH REMIND_CUSOR INTO tmp_dataids;
	WHILE(tmp_dataids IS NOT NULL) DO
		INSERT INTO ld_reminds_accepted
		SELECT * FROM ld_reminds WHERE FIND_IN_SET(remindsid,tmp_dataids);

		DELETE FROM ld_reminds WHERE FIND_IN_SET(remindsid,tmp_dataids);

		FETCH REMIND_CUSOR INTO tmp_dataids;
	END WHILE;
	CLOSE REMIND_CUSOR;

END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `ldcrm_resetoutinfo_bychangepara` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8 */ ;
/*!50003 SET character_set_results = utf8 */ ;
/*!50003 SET collation_connection  = utf8_general_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'NO_AUTO_CREATE_USER,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE  PROCEDURE `ldcrm_resetoutinfo_bychangepara`()
BEGIN
                    
                    	UPDATE ld_outboundorder SET presence='未出库' WHERE approvestatus='未提交' AND EXISTS (SELECT 1 FROM ld_systems_deploy WHERE  deploy_type=48 AND deploy_value=0);
                    	UPDATE ld_outboundorder SET approvestatus='已批准' WHERE presence='已出库' AND approvestatus='未提交' AND EXISTS (SELECT 1 FROM ld_systems_deploy WHERE  deploy_type=48 AND deploy_value=0);
                    
                    	IF EXISTS (SELECT 1 FROM ld_outboundorder a LEFT JOIN ld_outboundorderdetail b ON b.id=a.out_id WHERE b.entitytype='SalesOrder' LIMIT 1) THEN
                    		
                    		SET @disable_triggers=1;
                    		UPDATE ld_salesorderdetail a
                    		LEFT JOIN (
                    			SELECT
                    				entitytypeid,
                    				parent_lineitem_id,
                    				SUM(quantity) AS out_qty
                    			FROM ld_outboundorder a
                    			LEFT JOIN ld_outboundorderdetail b ON b.id=a.out_id
                    			WHERE a.deleted=0
                    				AND a.approvestatus<>'已拒绝'
                    				AND b.entitytypeid>0
                    				AND (
                    					CASE
                    						WHEN EXISTS (SELECT 1 FROM ld_systems_deploy WHERE deploy_type=48 AND deploy_value=0) THEN a.approvestatus='已批准'
                    						ELSE 1=1
                    					END)
                    			GROUP BY parent_lineitem_id
                    		) b ON b.parent_lineitem_id=a.lineitem_id
                    		SET a.haveoutproductcount=IFNULL(b.out_qty,0),a.balanceoutproductcount=a.quantity-IFNULL(b.out_qty,0);
                    
                    		SET @disable_triggers=NULL;
                    
                    		
                    		SET @disable_triggers=1;
                    		UPDATE ld_salesorder s
                    		SET s.stockpresence=(CASE
                    				WHEN NOT EXISTS (SELECT 1 FROM ld_outboundorder a LEFT JOIN ld_outboundorderdetail b ON b.id=a.out_id WHERE a.deleted=0 AND a.approvestatus<>'已拒绝' AND b.entitytypeid=s.salesorderid) THEN '未出库'
                    				WHEN NOT EXISTS (SELECT 1 FROM ld_salesorderdetail WHERE id=s.salesorderid AND quantity>0 AND haveoutproductcount>0) THEN '生成出库单'
                    				WHEN NOT EXISTS (SELECT 1 FROM ld_salesorderdetail WHERE id=s.salesorderid AND quantity>0 AND balanceoutproductcount>0) THEN '全部出库'
                    				ELSE '部分出库'
                    			END);
                    		SET @disable_triggers=NULL;
                    	END IF;
                    
                    	IF EXISTS (SELECT 1 FROM ld_outboundorder a LEFT JOIN ld_outboundorderdetail b ON b.id=a.out_id WHERE b.entitytype='ServiceContracts' LIMIT 1) THEN
                    		
                    		SET @disable_triggers=1;
                    		UPDATE ld_servicecontractsdetail a
                    		LEFT JOIN (
                    			SELECT
                    				entitytypeid,
                    				parent_lineitem_id,
                    				SUM(quantity) AS out_qty
                    			FROM ld_outboundorder a
                    			LEFT JOIN ld_outboundorderdetail b ON b.id=a.out_id
                    			WHERE a.deleted=0
                    				AND a.approvestatus<>'已拒绝'
                    				AND b.entitytypeid>0
                    				AND (
                    					CASE
                    						WHEN EXISTS (SELECT 1 FROM ld_systems_deploy WHERE deploy_type=48 AND deploy_value=0) THEN a.approvestatus='已批准'
                    						ELSE 1=1
                    					END)
                    			GROUP BY parent_lineitem_id
                    		) b ON b.parent_lineitem_id=a.lineitem_id
                    		SET a.haveoutproductcount=IFNULL(b.out_qty,0),a.balanceoutproductcount=a.quantity-IFNULL(b.out_qty,0);
                    
                    		SET @disable_triggers=NULL;
                    
                    		
                    		SET @disable_triggers=1;
                    		UPDATE ld_servicecontracts s
                    		SET s.stockpresence=(CASE
                    				WHEN NOT EXISTS (SELECT 1 FROM ld_outboundorder a LEFT JOIN ld_outboundorderdetail b ON b.id=a.out_id WHERE a.deleted=0 AND a.approvestatus<>'已拒绝' AND b.entitytypeid=s.servicecontractsid) THEN '未出库'
                    				WHEN NOT EXISTS (SELECT 1 FROM ld_servicecontractsdetail WHERE id=s.servicecontractsid AND quantity>0 AND haveoutproductcount>0) THEN '生成出库单'
                    				WHEN NOT EXISTS (SELECT 1 FROM ld_servicecontractsdetail WHERE id=s.servicecontractsid AND quantity>0 AND balanceoutproductcount>0) THEN '全部出库'
                    				ELSE '部分出库'
                    			END);
                    		SET @disable_triggers=NULL;
                    	END IF;
                    
                    
                    	IF EXISTS (SELECT 1 FROM ld_outboundorder a LEFT JOIN ld_outboundorderdetail b ON b.id=a.out_id WHERE b.entitytype='Invoice' LIMIT 1) THEN
                    		
                    		SET @disable_triggers=1;
                    		UPDATE ld_invoicedetail a
                    		LEFT JOIN (
                    			SELECT
                    				entitytypeid,
                    				parent_lineitem_id,
                    				SUM(quantity) AS out_qty
                    			FROM ld_outboundorder a
                    			LEFT JOIN ld_outboundorderdetail b ON b.id=a.out_id
                    			WHERE a.deleted=0
                    				AND a.approvestatus<>'已拒绝'
                    				AND b.entitytypeid>0
                    				AND (
                    					CASE
                    						WHEN EXISTS (SELECT 1 FROM ld_systems_deploy WHERE deploy_type=48 AND deploy_value=0) THEN a.approvestatus='已批准'
                    						ELSE 1=1
                    					END)
                    			GROUP BY parent_lineitem_id
                    		) b ON b.parent_lineitem_id=a.lineitem_id
                    		SET a.haveoutproductcount=IFNULL(b.out_qty,0),a.balanceoutproductcount=a.quantity-IFNULL(b.out_qty,0);
                    
                    		SET @disable_triggers=NULL;
                    
                    		
                    		SET @disable_triggers=1;
                    		UPDATE ld_invoice s
                    		SET s.stockpresence=(CASE
                    				WHEN NOT EXISTS (SELECT 1 FROM ld_outboundorder a LEFT JOIN ld_outboundorderdetail b ON b.id=a.out_id WHERE a.deleted=0 AND a.approvestatus<>'已拒绝' AND b.entitytypeid=s.invoiceid) THEN '未出库'
                    				WHEN NOT EXISTS (SELECT 1 FROM ld_invoicedetail WHERE id=s.invoiceid AND quantity>0 AND haveoutproductcount>0) THEN '生成出库单'
                    				WHEN NOT EXISTS (SELECT 1 FROM ld_invoicedetail WHERE id=s.invoiceid AND quantity>0 AND balanceoutproductcount>0) THEN '全部出库'
                    				ELSE '部分出库'
                    			END);
                    		SET @disable_triggers=NULL;
                    	END IF;
                    
                    	IF EXISTS (SELECT 1 FROM ld_outboundorder a LEFT JOIN ld_outboundorderdetail b ON b.id=a.out_id WHERE b.entitytype='Stock' LIMIT 1) THEN
                    		
                    		SET @disable_triggers=1;
                    		UPDATE ld_stockdetail a
                    		LEFT JOIN (
                    			SELECT
                    				entitytypeid,
                    				parent_lineitem_id,
                    				SUM(quantity) AS out_qty
                    			FROM ld_outboundorder a
                    			LEFT JOIN ld_outboundorderdetail b ON b.id=a.out_id
                    			WHERE a.deleted=0
                    				AND a.approvestatus<>'已拒绝'
                    				AND b.entitytypeid>0
                    				AND (
                    					CASE
                    						WHEN EXISTS (SELECT 1 FROM ld_systems_deploy WHERE deploy_type=48 AND deploy_value=0) THEN a.approvestatus='已批准'
                    						ELSE 1=1
                    					END)
                    			GROUP BY parent_lineitem_id
                    		) b ON b.parent_lineitem_id=a.lineitem_id
                    		SET a.haveoutproductcount=IFNULL(b.out_qty,0),a.balanceoutproductcount=a.quantity-IFNULL(b.out_qty,0);
                    
                    		SET @disable_triggers=NULL;
                    
                    		
                    		SET @disable_triggers=1;
                    		UPDATE ld_stock s
                    		SET s.stockpresence=(CASE
                    				WHEN NOT EXISTS (SELECT 1 FROM ld_outboundorder a LEFT JOIN ld_outboundorderdetail b ON b.id=a.out_id WHERE a.deleted=0 AND a.approvestatus<>'已拒绝' AND b.entitytypeid=s.stock_id) THEN '未出库'
                    				WHEN NOT EXISTS (SELECT 1 FROM ld_stockdetail WHERE id=s.stock_id AND quantity>0 AND haveoutproductcount>0) THEN '生成出库单'
                    				WHEN NOT EXISTS (SELECT 1 FROM ld_stockdetail WHERE id=s.stock_id AND quantity>0 AND balanceoutproductcount>0) THEN '全部出库'
                    				ELSE '部分出库'
                    			END);
                    		SET @disable_triggers=NULL;
                    	END IF;
                    
                    
                    
                    	UPDATE ld_stock SET presence='未入库' WHERE approvestatus='未提交' AND EXISTS (SELECT 1 FROM ld_systems_deploy WHERE  deploy_type=48 AND deploy_value=0);
                    	UPDATE ld_stock SET approvestatus='已批准' WHERE presence='已入库' AND approvestatus='未提交' AND EXISTS (SELECT 1 FROM ld_systems_deploy WHERE  deploy_type=48 AND deploy_value=0);
                    
                    	IF EXISTS (SELECT 1 FROM ld_stock a LEFT JOIN ld_stockdetail b ON b.id=a.stock_id WHERE b.entitytype='PurchaseOrder' LIMIT 1) THEN
                    		
                    		SET @disable_triggers=1;
                    		UPDATE ld_purchaseorderdetail a
                    		LEFT JOIN (
                    			SELECT
                    				entitytypeid,
                    				parent_lineitem_id,
                    				SUM(quantity) AS in_qty
                    			FROM ld_stock a
                    			LEFT JOIN ld_stockdetail b ON b.id=a.stock_id
                    			WHERE a.deleted=0
                    				AND a.approvestatus<>'已拒绝'
                    				AND b.entitytypeid>0
                    				AND (
                    					CASE
                    						WHEN EXISTS (SELECT 1 FROM ld_systems_deploy WHERE deploy_type=48 AND deploy_value=0) THEN a.approvestatus='已批准'
                    						ELSE 1=1
                    					END)
                    			GROUP BY parent_lineitem_id
                    		) b ON b.parent_lineitem_id=a.lineitem_id
                    		SET a.havepurchasecount=IFNULL(b.in_qty,0),a.balancepurchasecount=a.quantity-IFNULL(b.in_qty,0);
                    
                    		SET @disable_triggers=NULL;
                    
                    		
                    		SET @disable_triggers=1;
                    		UPDATE ld_purchaseorder s
                    		SET s.stockpresence=(CASE
                    				WHEN NOT EXISTS (SELECT 1 FROM ld_stock a LEFT JOIN ld_stockdetail b ON b.id=a.stock_id WHERE a.deleted=0 AND a.approvestatus<>'已拒绝' AND b.entitytypeid=s.purchaseorderid) THEN '未入库'
                    				WHEN NOT EXISTS (SELECT 1 FROM ld_purchaseorderdetail WHERE id=s.purchaseorderid AND quantity>0 AND haveoutproductcount>0) THEN '生成入库单'
                    				WHEN NOT EXISTS (SELECT 1 FROM ld_purchaseorderdetail WHERE id=s.purchaseorderid AND quantity>0 AND balanceoutproductcount>0) THEN '全部入库'
                    				ELSE '部分入库'
                    			END);
                    		SET @disable_triggers=NULL;
                    	END IF;
                    
                    	IF EXISTS (SELECT 1 FROM ld_stock a LEFT JOIN ld_stockdetail b ON b.id=a.stock_id WHERE b.entitytype='PurchaseInvoice' LIMIT 1) THEN
                    		
                    		SET @disable_triggers=1;
                    		UPDATE ld_purchaseinvoicedetail a
                    		LEFT JOIN (
                    			SELECT
                    				entitytypeid,
                    				parent_lineitem_id,
                    				SUM(quantity) AS in_qty
                    			FROM ld_stock a
                    			LEFT JOIN ld_stockdetail b ON b.id=a.stock_id
                    			WHERE a.deleted=0
                    				AND a.approvestatus<>'已拒绝'
                    				AND b.entitytypeid>0
                    				AND (
                    					CASE
                    						WHEN EXISTS (SELECT 1 FROM ld_systems_deploy WHERE deploy_type=48 AND deploy_value=0) THEN a.approvestatus='已批准'
                    						ELSE 1=1
                    					END)
                    			GROUP BY parent_lineitem_id
                    		) b ON b.parent_lineitem_id=a.lineitem_id
                    		SET a.havepurchasecount=IFNULL(b.in_qty,0),a.balancepurchasecount=a.quantity-IFNULL(b.in_qty,0);
                    
                    		SET @disable_triggers=NULL;
                    
                    		
                    		SET @disable_triggers=1;
                    		UPDATE ld_purchaseinvoice s
                    		SET s.stockpresence=(CASE
                    				WHEN NOT EXISTS (SELECT 1 FROM ld_stock a LEFT JOIN ld_stockdetail b ON b.id=a.stock_id WHERE a.deleted=0 AND a.approvestatus<>'已拒绝' AND b.entitytypeid=s.purchaseorderid) THEN '未入库'
                    				WHEN NOT EXISTS (SELECT 1 FROM ld_purchaseinvoicedetail WHERE id=s.purchaseorderid AND quantity>0 AND haveoutproductcount>0) THEN '生成入库单'
                    				WHEN NOT EXISTS (SELECT 1 FROM ld_purchaseinvoicedetail WHERE id=s.purchaseorderid AND quantity>0 AND balanceoutproductcount>0) THEN '全部入库'
                    				ELSE '部分入库'
                    			END);
                    		SET @disable_triggers=NULL;
                    	END IF;
                    
                    	SET @disable_triggers=1;
                    	UPDATE ld_products p
                    	LEFT JOIN (
                    		SELECT
                    			a.wareid,
                    			a.productid,
                    			a.batchtext,
                    			SUM(a.inventory_qty) AS inventory_qty
                    		FROM (
                    			SELECT
                    				a.warehouseid AS wareid,
                    				a.productid,
                    				a.batchtext,
                    				a.lastqty AS inventory_qty
                    			FROM ld_warehousecondtions a
                    			LEFT JOIN ld_products c ON c.productid=a.productid
                    			WHERE a.modulename='库存初始化'
                    				AND a.type='确认初始库存'
                    			UNION ALL
                    			SELECT
                    				a.wareid,
                    				c.productid,
                    				c.batchtext,
                    				c.quantity
                    			FROM ld_stock a
                    			LEFT JOIN ld_stockdetail c ON c.id=a.stock_id
                    			LEFT JOIN ld_products p ON p.productid=c.productid
                    			WHERE a.deleted=0
                    				AND a.approvestatus<>'已拒绝'
                    				AND (
                    					CASE
                    						WHEN EXISTS (SELECT 1 FROM ld_systems_deploy WHERE deploy_type=48 AND deploy_value=1) THEN 1=1
                    						ELSE a.approvestatus='已批准'
                    					END)
                    			UNION ALL
                    			SELECT
                    				a.wareid,
                    				c.productid,
                    				c.batchtext,
                    				c.quantity
                    			FROM ld_salesback a
                    			LEFT JOIN ld_salesbackdetail c ON c.id=a.salesbackid
                    			LEFT JOIN ld_products p ON p.productid=c.productid
                    			WHERE a.deleted=0
                    				AND a.salesbackstatus<>'中止'
                    				AND (
                    					CASE
                    						WHEN EXISTS (SELECT 1 FROM ld_systems_deploy WHERE deploy_type=48 AND deploy_value=1) THEN 1=1
                    						ELSE a.approvestatus='已批准'
                    					END)
                    			UNION ALL
                    			SELECT
                    				c.wareid,
                    				c.productid,
                    				c.batchtext,
                    				0-c.quantity
                    			FROM ld_outboundorder a
                    			LEFT JOIN ld_outboundordercf b ON a.out_id=b.out_id
                    			LEFT JOIN ld_outboundorderdetail c ON c.id=a.out_id
                    			LEFT JOIN ld_outboundorderdetailscf d ON d.lineitem_id=c.lineitem_id
                    			LEFT JOIN ld_products p ON p.productid=c.productid
                    			WHERE a.deleted=0
                    				AND a.approvestatus<>'已拒绝'
                    				AND (
                    					CASE
                    						WHEN EXISTS (SELECT 1 FROM ld_systems_deploy WHERE deploy_type=48 AND deploy_value=1) THEN 1=1
                    						ELSE a.approvestatus='已批准'
                    					END)
                    			UNION ALL
                    			SELECT
                    				a.wareid,
                    				c.productid,
                    				c.batchtext,
                    				0-c.quantity
                    			FROM ld_purchaseback a
                    			LEFT JOIN ld_purchasebackdetail c ON c.id=a.purchasebackid
                    			LEFT JOIN ld_products p ON p.productid=c.productid
                    			WHERE a.deleted=0
                    				AND a.purchasebackstatus<>'中止'
                    				AND (
                    					CASE
                    						WHEN EXISTS (SELECT 1 FROM ld_systems_deploy WHERE deploy_type=48 AND deploy_value=1) THEN 1=1
                    						ELSE a.purchasebackstatus='结束'
                    					END)
                    			UNION ALL
                    			SELECT
                    				a.inwarehouse,
                    				c.productid,
                    				c.batchtext,
                    				c.quantity
                    			FROM ld_warehousetransfer a
                    			LEFT JOIN ld_warehousetransferdetail c ON c.id=a.warehousetransferid
                    			LEFT JOIN ld_products p ON p.productid=c.productid
                    			WHERE a.deleted=0
                    				AND (
                    					CASE
                    						WHEN EXISTS (SELECT 1 FROM ld_systems_deploy WHERE deploy_type=48 AND deploy_value=1) THEN 1=1
                    						ELSE a.transferstatus='已审核'
                    					END)
                    			UNION ALL
                    			SELECT
                    				a.outwarehouse,
                    				c.productid,
                    				c.batchtext,
                    				0-c.quantity
                    			FROM ld_warehousetransfer a
                    			LEFT JOIN ld_warehousetransferdetail c ON c.id=a.warehousetransferid
                    			LEFT JOIN ld_products p ON p.productid=c.productid
                    			WHERE a.deleted=0
                    				AND (
                    					CASE
                    						WHEN EXISTS (SELECT 1 FROM ld_systems_deploy WHERE deploy_type=48 AND deploy_value=1) THEN 1=1
                    						ELSE a.transferstatus='已审核'
                    					END)
                    			UNION ALL
                    			SELECT
                    				a.wareid,
                    				c.productid,
                    				c.batchtext,
                    				c.profitloss
                    			FROM ld_checks a
                    			LEFT JOIN ld_checksdetail c ON c.id=a.id
                    			LEFT JOIN ld_products p ON p.productid=c.productid
                    			WHERE a.deleted=0
                    				AND (
                    					CASE
                    						WHEN EXISTS (SELECT 1 FROM ld_systems_deploy WHERE deploy_type=48 AND deploy_value=1) THEN 1=1
                    						ELSE a.presence='盘点结束'
                    					END)
                    		) a
                    		WHERE a.productid>0
                    		GROUP BY a.productid
                    	) a ON a.productid=p.productid
                    	SET p.qtyinstock=IFNULL(a.inventory_qty,0)
                    	WHERE p.deleted=0
                    		AND IFNULL(p.qtyinstock,0)<>IFNULL(a.inventory_qty,0);
                    
                    	SET @disable_triggers=NULL;
                        
                    end ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `ldcrm_reset_account_nolinkdays` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8 */ ;
/*!50003 SET character_set_results = utf8 */ ;
/*!50003 SET collation_connection  = utf8_general_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'NO_AUTO_CREATE_USER,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE  PROCEDURE `ldcrm_reset_account_nolinkdays`(
)
BEGIN
	SET @disable_triggers=1;
	UPDATE ld_account SET nolinkdays=DATEDIFF(CURDATE(),DATE_FORMAT(GREATEST(IFNULL(lastcontactdate,'1960-01-01' ),createdtime),'%Y-%m-%d'));
	SET @disable_triggers=NULL;
end ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `ldcrm_reset_approvenew` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8 */ ;
/*!50003 SET character_set_results = utf8 */ ;
/*!50003 SET collation_connection  = utf8_general_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'NO_AUTO_CREATE_USER,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE  PROCEDURE `ldcrm_reset_approvenew`(
	tmp_modulename VARCHAR(100)
)
BEGIN
	SET @mytabid=(SELECT tabid FROM ld_tab WHERE `name`=tmp_modulename);
	IF NOT EXISTS (SELECT 1 FROM ld_approve WHERE tabid=@mytabid AND isnewapprove='yes') THEN

		DELETE FROM ld_approvestep WHERE approveid IN (SELECT id FROM ld_approve WHERE tabid=@mytabid);
		DELETE FROM ld_approve2role WHERE approveid IN (SELECT id FROM ld_approve WHERE tabid=@mytabid);
		DELETE FROM ld_approve2user WHERE approveid IN (SELECT id FROM ld_approve WHERE tabid=@mytabid);
		DELETE FROM ld_approvecanceladvfilter WHERE approveid IN (SELECT id FROM ld_approve WHERE tabid=@mytabid);
		DELETE FROM ld_approvecanceladvfilter_grouping WHERE approveid IN (SELECT id FROM ld_approve WHERE tabid=@mytabid);
		DELETE FROM ld_approvereminds WHERE stepid IN (SELECT id FROM ld_approvestep WHERE approveid IN (SELECT id FROM ld_approve WHERE tabid=@mytabid));
		DELETE FROM ld_approve WHERE tabid=@mytabid;

		SET @max_approveid=(SELECT MAX(id) FROM ld_approve);
		SET @max_seq=(SELECT MAX(sequence) FROM ld_approve);
		SET @zh_modulename=(SELECT fieldlabel FROM ld_tranlabel WHERE tabid=@mytabid AND Relateid=@mytabid AND trantable='ld_tab' AND languagetype='zh' LIMIT 1);
		INSERT INTO ld_approve(
			id,
			tabid,
			name,
			status,
			smcreatorid,

			modifiedby,
			createdtime,
			modifiedtime,
			allowediting,
			finishedallowedit,

			default_on_new,
			default_on_submit,
			allowagainsubmit,
			finishedfield_allocatetype,
			isnewapprove,

			sequence
		)
		SELECT 
			@max_approveid+1,
			@mytabid,
			CONCAT(@zh_modulename,'预置审批流程'),
			0,
			1,

			1,
			NOW(),
			NOW(),
			0,
			'no',

			'yes',
			'yes',
			'no',
			'all',
			'yes',

			@max_seq+1;

		UPDATE ld_approve_seq SET id=(SELECT MAX(id) FROM ld_approve);

		INSERT INTO ld_approve2user(approveid,userid) SELECT @max_approveid+1,-1;

		SET @max_stepid=(SELECT MAX(id) FROM ld_approvestep);
		INSERT INTO ld_approvestep(
			id,
			approveid,
			name,
			ended,
			step,

			sequence,
			createdtime,
			modifiedtime,
			approvetype,
			specifyapproverid,
			
			alloweditbill,
			steptype,
			isnewstep,
			flowstepid,
			childids,

			branchflowstepid
		)
		SELECT
			@max_stepid+1,
			@max_approveid+1,
			'开始',
			NULL,
			NULL,

			1,
			NULL,
			NULL,
			NULL,
			1,
			
			NULL,
			'start',
			'yes',
			-1,
			1,

			-1;

		INSERT INTO ld_approvereminds(
			stepid,
			type,
			remindmethod,
			reminduser,
			remindcontent,

			reminduserid,
			remindcolumnname,
			remindtitle
		)
		SELECT 
			@max_stepid+1,
			0,
			'dialog',
			'approver',
			'有新的{modulelabel}需要审批，请及时处理！',

			NULL,
			NULL,
			'【{modulelabel}】审批通知';


		INSERT INTO ld_approvereminds(
			stepid,
			type,
			remindmethod,
			reminduser,
			remindcontent,

			reminduserid,
			remindcolumnname,
			remindtitle
		)
		SELECT 
			@max_stepid+1,
			1,
			'dialog',
			'smowner',
			'您负责的{modulelabel}已通过审批步骤{step}',

			NULL,
			NULL,
			'【{modulelabel}】审批结果通知';

		INSERT INTO ld_approvereminds(
			stepid,
			type,
			remindmethod,
			reminduser,
			remindcontent,

			reminduserid,
			remindcolumnname,
			remindtitle
		)
		SELECT 
			@max_stepid+1,
			2,
			'dialog',
			'smowner',
			'您负责的{modulelabel}未通过审批步骤{step}，原因：{description}',

			NULL,
			NULL,
			'【{modulelabel}】审批结果通知';

		INSERT INTO ld_approvestep(
			id,
			approveid,
			name,
			ended,
			step,

			sequence,
			createdtime,
			modifiedtime,
			approvetype,
			specifyapproverid,
			
			alloweditbill,
			steptype,
			isnewstep,
			flowstepid,
			childids,
			
			branchflowstepid
		)
		SELECT
			@max_stepid+2,
			@max_approveid+1,
			'一级审批',
			0,
			1,

			1,
			NOW(),
			NOW(),
			6,
			1,

			'no',
			'approver',
			'yes',
			1,
			NULL,
			
			-1;

		INSERT INTO ld_approvereminds(
			stepid,
			type,
			remindmethod,
			reminduser,
			remindcontent,

			reminduserid,
			remindcolumnname,
			remindtitle
		)
		SELECT 
			@max_stepid+2,
			0,
			'dialog',
			'approver',
			'有新的{modulelabel}需要审批，请及时处理！',

			NULL,
			NULL,
			'【{modulelabel}】审批通知';


		INSERT INTO ld_approvereminds(
			stepid,
			type,
			remindmethod,
			reminduser,
			remindcontent,

			reminduserid,
			remindcolumnname,
			remindtitle
		)
		SELECT 
			@max_stepid+2,
			1,
			'dialog',
			'smowner',
			'您负责的{modulelabel}已通过审批步骤{step}',

			NULL,
			NULL,
			'【{modulelabel}】审批结果通知';

		INSERT INTO ld_approvereminds(
			stepid,
			type,
			remindmethod,
			reminduser,
			remindcontent,

			reminduserid,
			remindcolumnname,
			remindtitle
		)
		SELECT 
			@max_stepid+2,
			2,
			'dialog',
			'smowner',
			'您负责的{modulelabel}未通过审批步骤{step}，原因：{description}',

			NULL,
			NULL,
			'【{modulelabel}】审批结果通知';

		UPDATE ld_approvestep_seq SET id=(SELECT MAX(id) FROM ld_approvestep);

	END IF;

end ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `ldcrm_reset_expensebudget_byid` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8 */ ;
/*!50003 SET character_set_results = utf8 */ ;
/*!50003 SET collation_connection  = utf8_general_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'NO_AUTO_CREATE_USER,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE  PROCEDURE `ldcrm_reset_expensebudget_byid`(
	tmp_mybillid TEXT
)
BEGIN

	DECLARE tmp_budgettype VARCHAR(100) DEFAULT '';
	DECLARE tmp_budgetindicators VARCHAR(100) DEFAULT '';
	
	DECLARE MY_RESETCUSOR CURSOR FOR 
					SELECT
						a.expensebudget_type,
						a.budget_indicators
					FROM ld_expensebudget a
					WHERE FIND_IN_SET(a.expensebudgetid,tmp_mybillid)
						AND a.expensebudget_type IN ('salesGoalBudget','salesAchievementBudget')
					GROUP BY a.expensebudget_type,a.budget_indicators;

	DECLARE CONTINUE HANDLER FOR SQLSTATE '02000' SET tmp_budgettype = NULL;

	OPEN MY_RESETCUSOR; 
	FETCH MY_RESETCUSOR INTO tmp_budgettype,tmp_budgetindicators;
	WHILE(tmp_budgettype IS NOT NULL) DO
		SET @exec_resetbudgetinfo='';
		IF tmp_budgettype ='salesGoalBudget' THEN
			SET @exec_resetbudgetinfo=(
				SELECT
					CONCAT("UPDATE ld_expensebudget a ","\r\n",
						"LEFT JOIN ld_expensebudgetdetail b ON b.id=a.expensebudgetid ","\r\n",
						"SET ","\r\n",
						"	b.reference_amount=","IFNULL((SELECT SUM(",IFNULL(a.budget_column,''),") FROM ld_salestarget WHERE userid=b.lin_users_id AND CONCAT(targetyear,'-',targetmouth,'-01') BETWEEN a.indicators_start_date AND a.indicators_end_date),0),","\r\n",
						"	b.amount=IFNULL(b.budget_rate,0)*0.01*","IFNULL((SELECT SUM(",IFNULL(a.budget_column,''),") FROM ld_salestarget WHERE userid=b.lin_users_id AND CONCAT(targetyear,'-',targetmouth,'-01') BETWEEN a.indicators_start_date AND a.indicators_end_date),0),","\r\n",
						"	b.budget_amount=IFNULL(b.adjustment_amount,0)+IFNULL(b.budget_rate,0)*0.01*","IFNULL((SELECT SUM(",IFNULL(a.budget_column,''),") FROM ld_salestarget WHERE userid=b.lin_users_id AND CONCAT(targetyear,'-',targetmouth,'-01') BETWEEN a.indicators_start_date AND a.indicators_end_date),0)","\r\n",
						"WHERE FIND_IN_SET(a.expensebudgetid,'",tmp_mybillid,"') ","\r\n",
							"	AND a.expensebudget_type='salesGoalBudget' ","\r\n",
							"	AND a.budget_indicators='",tmp_budgetindicators,"'"
						) AS exex_sql
				FROM (
					SELECT 
						`name` AS indicators_type,
						`columns` AS budget_column 
					FROM ld_expensebudget_totalcolumns 
					WHERE type='salesGoalBudget' 
					GROUP BY `name`
				) a
				WHERE a.indicators_type=tmp_budgetindicators
			);
		ELSE
			SET @exec_resetbudgetinfo=(
				SELECT
					CONCAT("UPDATE ld_expensebudget a ","\r\n",
						"LEFT JOIN ld_expensebudgetdetail b ON b.id=a.expensebudgetid ","\r\n",
						"SET ","\r\n",
						"	b.reference_amount=(",total_sql,"),","\r\n",
						"	b.amount=IFNULL(b.budget_rate,0)*0.01*(",total_sql,"),","\r\n",
						"	b.budget_amount=IFNULL(b.adjustment_amount,0)+IFNULL(b.budget_rate,0)*0.01*(",total_sql,")","\r\n",
						"WHERE FIND_IN_SET(a.expensebudgetid,'",tmp_mybillid,"') ","\r\n",
							"	AND a.expensebudget_type='salesAchievementBudget' ","\r\n",
							"	AND a.budget_indicators='",tmp_budgetindicators,"'"
						) AS exex_sql
				FROM (
					SELECT
						indicators_type,
						budget_column,
						modulename,
						GROUP_CONCAT(CONCAT("IFNULL((SELECT SUM(",IFNULL(a.budget_column,''),") FROM ",(SELECT CONCAT(main_tablename,' LEFT JOIN ',custom_tablename,' ON ',main_tablename,'.',primary_key,'=',custom_tablename,'.',primary_key ) FROM ld_tab WHERE `name`=a.modulename)," WHERE deleted=0 AND (CASE WHEN '",a.approved,"'='yes' THEN approvestatus='已批准' ELSE 1=1 END) AND approvestatus<>'已拒绝' AND smownerid=b.lin_users_id AND ",a.time_condition," BETWEEN a.indicators_start_date AND a.indicators_end_date),0)") SEPARATOR '+') AS total_sql
					FROM (
						SELECT 
							`name` AS indicators_type,
							`columns` AS budget_column,
							modulename,
							CASE
								WHEN EXISTS (SELECT 1 FROM ld_field WHERE tablename=LEFT(time_condition_field,LOCATE('.',time_condition_field)-1) AND columnname=RIGHT(time_condition_field,LENGTH(time_condition_field)-LOCATE('.',time_condition_field)) AND presence<>1) THEN time_condition_field
								ELSE time_condition_default
							END AS time_condition,
							approved
						FROM ld_expensebudget_totalcolumns 
						WHERE type='salesAchievementBudget' 
						GROUP BY `name`,`columns`
					) a
					GROUP BY indicators_type
				) a
				WHERE a.indicators_type=tmp_budgetindicators
			);
		END IF;
		
		IF IFNULL(@exec_resetbudgetinfo,'')<>'' THEN
			SET @disable_triggers=1;
			PREPARE resetbudgetinfostmt FROM @exec_resetbudgetinfo;
			EXECUTE resetbudgetinfostmt;
			DEALLOCATE PREPARE resetbudgetinfostmt;
			SET @disable_triggers=NULL;
		END IF;
		FETCH MY_RESETCUSOR INTO tmp_budgettype,tmp_budgetindicators;
	END WHILE;
	CLOSE MY_RESETCUSOR;
	
	UPDATE ld_expensebudget SET total=(SELECT SUM(budget_amount) FROM ld_expensebudgetdetail WHERE id=ld_expensebudget.expensebudgetid) WHERE FIND_IN_SET(expensebudgetid,tmp_mybillid);

END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `ldcrm_reset_nianjianinfo` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8 */ ;
