			prepare stmt23 from @sql;
			execute stmt23;
			deallocate  prepare  stmt23;
			set @sql=Concat('insert into ld_tranlabel(languagetype,trantable,tabid,relateid,fieldlabel)
									select "en","ld_field",',ttabid,",",@fieldid,",'已付总额' from dual 		
